window.BlessData.files["Sources-Bless"] = {"group":"Sources-Bless","files":[{"path":"Sources/Bless/Bless.swift","status":"added","lang":"swift","hunks":[[1,0,1,26]],"header":{"lines":[1,21],"target":"Bless","what":[8,19],"pin":[20,20],"in":null,"out":null,"style":"swift"},"marks":[],"first":0,"scopes":[["E","BlessVersion",null,"public",24,24,[24,25],26,[23,23],-1,0,"a",[]]],"old":"","new":"//\n//  Bless.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/13/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The module's front page. Bless holds a language model's reply until a person blesses it:\n//        the reply becomes a Petition at a Gate, a reviewer rules on it (bless, amend or withhold),\n//        and only a Release reaches the recipient. The pattern, for any InferenceProvider:\n//\n//            let gate = Gate()\n//            let blessed = Blessed(upstream: model, gate: gate) { request in\n//                Routing(conversationID: \"visit-42\", recipient: patient,\n//                        reviewers: [doctor.party], policy: Policy(deadline: .seconds(4 * 3600)))\n//            }\n//            let reply = try await blessed.complete(request)   // returns only once it is blessed\n//\n//        and, on the reviewer's side, `try await gate.decide(id, .bless, as: doctor)`.\n//  PIN:  No type is named Bless (the module's name); the version lives on BlessVersion.\n//\n\n/// The library's version, as the README and the site name it.\npublic enum BlessVersion {\n    public static let string = \"0.1.0\"\n}\n"},{"path":"Sources/Bless/Chat/ChatDelta.swift","status":"added","lang":"swift","hunks":[[1,0,1,55]],"header":{"lines":[1,12],"target":"Bless","what":[8,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1,"scopes":[["S","ChatDelta",null,"public",16,16,[16,45],36,null,-1,0,"a"],["i","init",["role","content","finishReason","id","model","held"],"public",27,27,[28,83],35,null,0,0,"a"],["X","AsyncThrowingStream",null,"",38,38,[38,79],55,null,-1,0,"a"],["f","assembled",["model"],"public",41,41,[41,70],54,[39,40],2,0,"a"]],"old":"","new":"//\n//  ChatDelta.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: One piece of a streamed reply. A provider's stream is a run of deltas whose `content`\n//        concatenates to the reply. `held` is Bless's own: Blessed's stream sends one delta\n//        carrying only the petition's id when the reply is held for review, before anything\n//        else, so a client can say \"waiting for your doctor\" without seeing a word of the draft.\n//\n\nimport Foundation\n\npublic struct ChatDelta: Sendable, Equatable {\n    public var role: ChatRole?\n    public var content: String?\n    public var finishReason: FinishReason?\n    /// The provider's id for the reply, when its stream names one.\n    public var id: String?\n    /// The model writing the reply, when its stream names one.\n    public var model: String?\n    /// Set only by Blessed: the reply is held as this petition. Never carries content.\n    public var held: Petition.ID?\n\n    public init(role: ChatRole? = nil, content: String? = nil, finishReason: FinishReason? = nil,\n                id: String? = nil, model: String? = nil, held: Petition.ID? = nil) {\n        self.role = role\n        self.content = content\n        self.finishReason = finishReason\n        self.id = id\n        self.model = model\n        self.held = held\n    }\n}\n\nextension AsyncThrowingStream where Element == ChatDelta, Failure == any Error {\n    /// The whole reply a stream spells out, read to its end. `model` names the model when the\n    /// stream does not.\n    public func assembled(model: String) async throws -> ChatResponse {\n        var text = \"\"\n        var finish: FinishReason?\n        var id: String?\n        var seen: String?\n        for try await delta in self {\n            text += delta.content ?? \"\"\n            finish = delta.finishReason ?? finish\n            id = id ?? delta.id\n            seen = seen ?? delta.model\n        }\n        return ChatResponse(id: id ?? \"stream-\\(UUID().uuidString.lowercased())\", model: seen ?? model,\n                            message: .assistant(text), finishReason: finish ?? .stop)\n    }\n}\n"},{"path":"Sources/Bless/Chat/ChatMessage.swift","status":"added","lang":"swift","hunks":[[1,0,1,29]],"header":{"lines":[1,9],"target":"Bless","what":[8,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":5,"scopes":[["E","ChatRole",null,"public",13,13,[13,62],15,null,-1,0,"a",["system","user","assistant"]],["S","ChatMessage",null,"public",17,17,[17,66],29,null,-1,0,"a"],["i","init",["role","content"],"public",21,21,[21,49],24,null,1,0,"a"],["f","system",["_"],"public static",26,26,[26,64],26,null,1,8,"a"],["f","user",["_"],"public static",27,27,[27,62],27,null,1,8,"a"],["f","assistant",["_"],"public static",28,28,[28,67],28,null,1,8,"a"]],"old":"","new":"//\n//  ChatMessage.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: One turn of a conversation, in the shape every chat API shares: a role and its text.\n//\n\nimport Foundation\n\npublic enum ChatRole: String, Codable, Sendable, CaseIterable {\n    case system, user, assistant\n}\n\npublic struct ChatMessage: Codable, Sendable, Equatable, Hashable {\n    public var role: ChatRole\n    public var content: String\n\n    public init(role: ChatRole, content: String) {\n        self.role = role\n        self.content = content\n    }\n\n    public static func system(_ content: String) -> ChatMessage { ChatMessage(role: .system, content: content) }\n    public static func user(_ content: String) -> ChatMessage { ChatMessage(role: .user, content: content) }\n    public static func assistant(_ content: String) -> ChatMessage { ChatMessage(role: .assistant, content: content) }\n}\n"},{"path":"Sources/Bless/Chat/ChatRequest.swift","status":"added","lang":"swift","hunks":[[1,0,1,30]],"header":{"lines":[1,11],"target":"Bless","what":[8,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":11,"scopes":[["S","ChatRequest",null,"public",15,15,[15,56],30,null,-1,0,"a"],["i","init",["model","messages","temperature","maxTokens","extra"],"public",22,22,[23,51],29,null,0,0,"a"]],"old":"","new":"//\n//  ChatRequest.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A chat-completion request, provider-neutral: the model, the conversation so far, and\n//        the sampling settings most layers share. `extra` carries top-level fields a particular\n//        layer needs beside them (Sewn's required `sewn` object, for one).\n//\n\nimport Foundation\n\npublic struct ChatRequest: Codable, Sendable, Equatable {\n    public var model: String\n    public var messages: [ChatMessage]\n    public var temperature: Double?\n    public var maxTokens: Int?\n    public var extra: [String: JSONValue]?\n\n    public init(model: String, messages: [ChatMessage], temperature: Double? = nil, maxTokens: Int? = nil,\n                extra: [String: JSONValue]? = nil) {\n        self.model = model\n        self.messages = messages\n        self.temperature = temperature\n        self.maxTokens = maxTokens\n        self.extra = extra\n    }\n}\n"},{"path":"Sources/Bless/Chat/ChatResponse.swift","status":"added","lang":"swift","hunks":[[1,0,1,60]],"header":{"lines":[1,10],"target":"Bless","what":[8,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":13,"scopes":[["E","FinishReason",null,"public",14,14,[14,52],29,null,-1,0,"a",["stop","length","contentFilter","toolCalls","other"]],["i","init",["wire"],"public",22,22,[22,30],24,[21,21],0,0,"a"],["i","init",["from"],"public",26,26,[26,50],28,null,0,0,"a"],["S","ChatResponse",null,"public",31,31,[31,57],60,null,-1,0,"a"],["S","Usage",null,"public",32,32,[32,54],42,null,3,0,"a"],["i","init",["promptTokens","completionTokens","totalTokens"],"public",37,37,[37,80],41,null,4,0,"a"],["i","init",["id","model","message","finishReason","usage","created"],"public",51,51,[52,59],59,null,3,0,"a"]],"old":"","new":"//\n//  ChatResponse.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A completed chat reply, provider-neutral: the provider's id for it, the model that wrote\n//        it, the assistant's message, why it stopped, and what it cost in tokens.\n//\n\nimport Foundation\n\npublic enum FinishReason: String, Codable, Sendable {\n    case stop\n    case length\n    case contentFilter = \"content_filter\"\n    case toolCalls = \"tool_calls\"\n    case other\n\n    /// A provider's finish reason; anything unknown reads as `.other`.\n    public init(wire: String) {\n        self = FinishReason(rawValue: wire) ?? .other\n    }\n\n    public init(from decoder: any Decoder) throws {\n        self.init(wire: try decoder.singleValueContainer().decode(String.self))\n    }\n}\n\npublic struct ChatResponse: Codable, Sendable, Equatable {\n    public struct Usage: Codable, Sendable, Equatable {\n        public var promptTokens: Int\n        public var completionTokens: Int\n        public var totalTokens: Int\n\n        public init(promptTokens: Int, completionTokens: Int, totalTokens: Int) {\n            self.promptTokens = promptTokens\n            self.completionTokens = completionTokens\n            self.totalTokens = totalTokens\n        }\n    }\n\n    public var id: String\n    public var model: String\n    public var message: ChatMessage\n    public var finishReason: FinishReason?\n    public var usage: Usage?\n    public var created: Date?\n\n    public init(id: String, model: String, message: ChatMessage, finishReason: FinishReason? = .stop,\n                usage: Usage? = nil, created: Date? = nil) {\n        self.id = id\n        self.model = model\n        self.message = message\n        self.finishReason = finishReason\n        self.usage = usage\n        self.created = created\n    }\n}\n"},{"path":"Sources/Bless/Chat/InferenceProvider.swift","status":"added","lang":"swift","hunks":[[1,0,1,44]],"header":{"lines":[1,14],"target":"Bless","what":[8,11],"pin":[12,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":20,"scopes":[["P","InferenceProvider",null,"public",18,18,[18,44],25,null,-1,0,"a"],["v","name",null,"",20,20,[20,21],20,[19,19],0,9,"a"],["f","complete",["_"],"",22,22,null,22,[21,21],0,1,"a"],["f","stream",["_"],"",24,24,null,24,[23,23],0,1,"a"],["X","InferenceProvider",null,"",27,27,[27,28],44,null,-1,0,"a"],["f","stream",["_"],"public",28,28,[28,92],43,null,4,0,"a"]],"old":"","new":"//\n//  InferenceProvider.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The one thing Bless asks of an inference layer: answer a chat request, whole or as a\n//        stream. OpenAICompatibleProvider (BlessProviders) speaks the common wire; any other\n//        client conforms in a few lines. Blessed is itself an InferenceProvider, so a host swaps\n//        `model` for `Blessed(upstream: model, …)` and changes nothing else.\n//  PIN:  `stream` has a default over `complete` (one delta with the whole reply), so a layer\n//        that cannot stream still conforms; `name` is what a petition's provenance records.\n//\n\nimport Foundation\n\npublic protocol InferenceProvider: Sendable {\n    /// The provider's name, as a petition's provenance records it (\"mistral\", \"sewn\").\n    var name: String { get }\n    /// The whole reply.\n    func complete(_ request: ChatRequest) async throws -> ChatResponse\n    /// The reply as it is written. Cancelling the consumer cancels the request.\n    func stream(_ request: ChatRequest) -> AsyncThrowingStream<ChatDelta, any Error>\n}\n\nextension InferenceProvider {\n    public func stream(_ request: ChatRequest) -> AsyncThrowingStream<ChatDelta, any Error> {\n        AsyncThrowingStream { continuation in\n            let task = Task {\n                do {\n                    let response = try await complete(request)\n                    continuation.yield(ChatDelta(role: .assistant, content: response.message.content,\n                                                 finishReason: response.finishReason ?? .stop,\n                                                 id: response.id, model: response.model))\n                    continuation.finish()\n                } catch {\n                    continuation.finish(throwing: error)\n                }\n            }\n            continuation.onTermination = { _ in task.cancel() }\n        }\n    }\n}\n"},{"path":"Sources/Bless/Gate/Dispatcher.swift","status":"added","lang":"swift","hunks":[[1,0,1,17]],"header":{"lines":[1,11],"target":"Bless","what":[8,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":26,"scopes":[["P","Dispatcher",null,"public",15,15,[15,37],17,null,-1,0,"a"],["f","dispatch",["_","to"],"",16,16,null,16,null,0,1,"a"]],"old":"","new":"//\n//  Dispatcher.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The host's delivery path to a recipient (a push, a message in the patient's app, an\n//        SSE chunk). `Gate.dispatch(_:via:)` hands it only a verified Release and records in\n//        the ledger whether delivery succeeded.\n//\n\nimport Foundation\n\npublic protocol Dispatcher: Sendable {\n    func dispatch(_ release: Release, to recipient: Party) async throws\n}\n"},{"path":"Sources/Bless/Gate/Gate.swift","status":"added","lang":"swift","hunks":[[1,0,1,317]],"header":{"lines":[1,21],"target":"Bless","what":[8,14],"pin":[15,20],"in":null,"out":null,"style":"swift"},"marks":[[57,"Holding"],[80,"Deciding"],[156,"Releasing"],[201,"Reading"],[235,"Internals"]],"first":28,"scopes":[["A","Gate",null,"public",25,25,[25,18],317,null,-1,0,"a"],["i","init",["store","ledger","now","sleeper","ids"],"public",45,45,[47,56],53,[39,44],0,0,"a"],["f","stamp",[],"private",55,55,[55,33],55,null,0,8,"a"],["f","submit",["_","to","reviewers","policy"],"public",60,61,[61,126],78,[59,59],0,0,"a"],["f","decide",["_"],"public",83,84,[84,62],104,[82,82],0,0,"a"],["f","decide",["_","_","as","note"],"public",107,108,[108,131],111,[106,106],0,0,"a"],["f","decide",["_","_","by","note"],"public",114,115,[115,123],119,[113,113],0,0,"a"],["f","markViewed",["_","by"],"public",122,122,[122,76],127,[121,121],0,0,"a"],["f","withdraw",["_"],"public",130,131,[131,63],141,[129,129],0,0,"a"],["f","sweep",["now"],"public",145,146,[146,66],154,[143,144],0,0,"a"],["f","release",["for"],"public",161,161,[161,69],179,[158,160],0,0,"a"],["f","dispatch",["_","via"],"public",183,184,[184,101],199,[181,182],0,0,"a"],["f","petition",["_"],"public",204,204,[204,63],206,[203,203],0,0,"a"],["f","pending",["for"],"public",209,209,[209,76],214,[208,208],0,0,"a"],["f","petitions",[],"public",217,217,[217,49],219,[216,216],0,0,"a"],["f","observe",[],"public",222,222,[222,51],230,[221,221],0,0,"a"],["v","waiterCount",null,"",233,233,[233,25],233,[232,232],0,8,"a"],["f","lapseIfDue",["_","at"],"private",237,237,[237,76],244,null,0,0,"a"],["f","issue",["_"],"private",247,247,[247,63],260,[246,246],0,0,"a"],["f","transition",["_"],"private",262,262,[262,50],265,null,0,0,"a"],["f","broadcast",["_"],"private",267,267,[267,49],269,null,0,0,"a"],["f","stopObserving",["_"],"private",271,271,[271,46],273,null,0,0,"a"],["f","park",["_","deadline"],"private",276,276,[276,71],292,[275,275],0,0,"a"],["f","wait",["_","_"],"private",294,294,[294,62],306,null,0,0,"a"],["f","wake",["_","_"],"private",308,308,[308,56],312,null,0,0,"a"],["f","wakeAll",["_"],"private",314,314,[314,44],316,null,0,0,"a"]],"old":"","new":"//\n//  Gate.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Where replies wait. `submit` holds a draft as a petition; reviewers `decide` with sealed\n//        verdicts; `release(for:)` suspends until the petition is decided and returns the Release\n//        (or throws: withheld, expired, withdrawn). Every transition is saved to the petition\n//        store and written to the ledger in the same step, and announced to `observe()`rs.\n//        Deadlines: `sweep` lapses every due petition; `decide` and `release` lapse a due one on\n//        entry; a caller waiting on a petition with a deadline wakes itself when it passes. The\n//        Gate owns no timer.\n//  PIN:  Every method but `release(for:)` and `dispatch` is free of suspension points (the stores\n//        are synchronous), so each transition is atomic on the actor. Waiting is wake-and-recheck:\n//        a transition resumes every waiter on that petition with nothing, and each re-reads the\n//        store, so many waiters get the same Release and none is resumed twice. Cancelling a\n//        waiter only stops that waiter: the petition stays pending (a dropped connection must not\n//        cancel the doctor's review), and nothing is written. Only `withdraw` withdraws.\n//\n\nimport Foundation\n\npublic actor Gate {\n    public typealias Now = @Sendable () -> Date\n    public typealias Sleeper = @Sendable (Duration) async throws -> Void\n    public typealias IDs = @Sendable () -> Petition.ID\n\n    /// The audit log of every transition.\n    public nonisolated let ledger: Ledger\n    private let store: any PetitionStore\n    private let now: Now\n    private let sleeper: Sleeper\n    private let ids: IDs\n    private var waiters: [Petition.ID: [UUID: CheckedContinuation<Void, Never>]] = [:]\n    private var observers: [UUID: AsyncStream<Petition>.Continuation] = [:]\n\n    /// - Parameters:\n    ///   - store: where petitions are kept (memory by default).\n    ///   - ledger: where transitions are chained (memory by default).\n    ///   - now: the clock; tests pass a fixed one.\n    ///   - sleeper: how a waiter sleeps until a deadline; tests pass one that advances `now`.\n    ///   - ids: how petitions are named; random by default.\n    public init(store: any PetitionStore = MemoryPetitionStore(), ledger: Ledger = Ledger(),\n                now: @escaping Now = { Date() }, sleeper: @escaping Sleeper = { try await Task.sleep(for: $0) },\n                ids: @escaping IDs = { Petition.ID() }) {\n        self.store = store\n        self.ledger = ledger\n        self.now = now\n        self.sleeper = sleeper\n        self.ids = ids\n    }\n\n    private func stamp() -> Date { Canonical.stamp(now()) }\n\n    // MARK: Holding\n\n    /// Holds a draft for review and returns its petition. Nothing reaches the recipient yet.\n    @discardableResult\n    public func submit(_ draft: Draft, to recipient: Party, reviewers: [Party], policy: Policy = Policy()) throws -> Petition {\n        guard draft.proposed.role == .assistant else { throw BlessError.invalidDraft(\"the proposed message must be the assistant's\") }\n        guard !draft.proposed.content.isEmpty else { throw BlessError.invalidDraft(\"the proposed message is empty\") }\n        try policy.validate(reviewers: reviewers)\n        guard !reviewers.contains(where: { $0.id == recipient.id }) else {\n            throw BlessError.invalidPolicy(\"the recipient cannot review their own reply\")\n        }\n        let at = stamp()\n        let petition = Petition(id: ids(), conversationID: draft.conversationID, context: policy.trimmed(draft.context),\n                                proposed: draft.proposed, provenance: draft.provenance, recipient: recipient,\n                                reviewers: reviewers, policy: policy, submitted: at,\n                                deadline: policy.deadlineInterval.map { Canonical.stamp(at.addingTimeInterval($0)) })\n        guard try store.load(petition.id) == nil else { throw BlessError.invalidDraft(\"petition \\(petition.id) exists\") }\n        try store.save(petition)\n        try ledger.append(.submitted, petition: petition.id, digest: petition.digest, at: at)\n        broadcast(petition)\n        return petition\n    }\n\n    // MARK: Deciding\n\n    /// Applies a reviewer's verdict (sealed on their device) and returns the petition after it.\n    @discardableResult\n    public func decide(_ verdict: Verdict) throws -> Petition {\n        let at = stamp()\n        let petition = try lapseIfDue(verdict.petitionID, at: at)\n        guard let reviewer = petition.reviewer(verdict.reviewer) else { throw BlessError.notAReviewer(verdict.reviewer) }\n        if let key = reviewer.verifyingKey, verdict.signature != nil {\n            guard Seal.verify(verdict, verifyingKey: key) else { throw BlessError.badSeal(reviewer.id) }\n        } else if petition.policy.requiresSeal {\n            throw BlessError.sealRequired(reviewer.id)\n        }\n        let next = try petition.applying(verdict, at: at)\n        try store.save(next)\n        try ledger.append(.decided, petition: next.id, actor: reviewer.id, digest: verdict.endorsed ?? verdict.digest,\n                          code: verdict.ruling.kind.rawValue, at: at)\n        switch next.standing {\n        case .blessed: try ledger.append(.blessed, petition: next.id, digest: next.digest, at: at)\n        case .withheld: try ledger.append(.withheld, petition: next.id, actor: reviewer.id, digest: verdict.digest, at: at)\n        case .pending, .expired, .withdrawn: break\n        }\n        transition(next)\n        return next\n    }\n\n    /// Seals the ruling with the reviewer's key, on the petition's current text, and applies it.\n    @discardableResult\n    public func decide(_ id: Petition.ID, _ ruling: Ruling, as reviewer: ReviewerIdentity, note: String? = nil) throws -> Petition {\n        let petition = try lapseIfDue(id, at: stamp())\n        return try decide(try reviewer.verdict(ruling, on: petition, note: note, issued: now()))\n    }\n\n    /// Applies an unsealed ruling; refused with `.sealRequired` when the policy requires seals.\n    @discardableResult\n    public func decide(_ id: Petition.ID, _ ruling: Ruling, by reviewer: Party.ID, note: String? = nil) throws -> Petition {\n        let petition = try lapseIfDue(id, at: stamp())\n        return try decide(Verdict(petitionID: id, reviewer: reviewer, ruling: ruling, digest: petition.digest, note: note,\n                                  issued: now()))\n    }\n\n    /// Records that a reviewer opened the petition.\n    public func markViewed(_ id: Petition.ID, by reviewer: Party.ID) throws {\n        let at = stamp()\n        let petition = try lapseIfDue(id, at: at)\n        guard petition.reviewer(reviewer) != nil else { throw BlessError.notAReviewer(reviewer) }\n        try ledger.append(.viewed, petition: id, actor: reviewer, digest: petition.digest, at: at)\n    }\n\n    /// Ends a pending petition without a decision (the recipient left, the host cancelled).\n    @discardableResult\n    public func withdraw(_ id: Petition.ID) throws -> Petition {\n        let at = stamp()\n        var petition = try lapseIfDue(id, at: at)\n        guard petition.standing == .pending else { throw BlessError.alreadyDecided(id, petition.standing) }\n        petition.standing = .withdrawn\n        petition.decided = at\n        try store.save(petition)\n        try ledger.append(.withdrawn, petition: id, digest: petition.digest, at: at)\n        transition(petition)\n        return petition\n    }\n\n    /// Lapses every pending petition whose deadline has passed (by `now`, or the Gate's clock)\n    /// and returns them.\n    @discardableResult\n    public func sweep(now date: Date? = nil) throws -> [Petition] {\n        let at = Canonical.stamp(date ?? now())\n        var lapsed: [Petition] = []\n        for petition in try store.all() where petition.standing == .pending {\n            let after = try lapseIfDue(petition.id, at: at)\n            if after.standing != .pending { lapsed.append(after) }\n        }\n        return lapsed\n    }\n\n    // MARK: Releasing\n\n    /// Waits until the petition is decided, then returns its Release. Throws `.withheld`,\n    /// `.expired` or `.withdrawn` when there is nothing to release, and CancellationError when\n    /// the caller is cancelled (the petition stays pending).\n    public func release(for id: Petition.ID) async throws -> Release {\n        while true {\n            try Task.checkCancellation()\n            let petition = try lapseIfDue(id, at: stamp())\n            switch petition.standing {\n            case .pending:\n                try await park(id, deadline: petition.policy.onLapse == .hold ? nil : petition.deadline)\n            case .blessed:\n                return try issue(petition)\n            case .expired:\n                guard petition.fallback != nil else { throw BlessError.expired(id) }\n                return try issue(petition)\n            case .withheld:\n                throw BlessError.withheld(id, reason: petition.withheldReason ?? \"\")\n            case .withdrawn:\n                throw BlessError.withdrawn(id)\n            }\n        }\n    }\n\n    /// Delivers a decided petition's Release through the host's dispatcher, after verifying it,\n    /// and records the outcome.\n    @discardableResult\n    public func dispatch(_ id: Petition.ID, via dispatcher: some Dispatcher) async throws -> Release {\n        let petition = try lapseIfDue(id, at: stamp())\n        guard petition.standing == .blessed || petition.fallback != nil else { throw BlessError.notBlessed(id) }\n        let release = try issue(petition)\n        guard let current = try store.load(id) else { throw BlessError.unknownPetition(id) }\n        try release.verify(against: current)\n        do {\n            try await dispatcher.dispatch(release, to: current.recipient)\n        } catch {\n            try ledger.append(.failed, petition: id, actor: current.recipient.id, digest: release.digest,\n                              code: (error as? BlessError)?.code ?? \"dispatcher\", at: stamp())\n            throw error\n        }\n        try ledger.append(.dispatched, petition: id, actor: current.recipient.id, digest: release.digest, at: stamp())\n        return release\n    }\n\n    // MARK: Reading\n\n    /// The petition as it stands (lapsed first, if it is due).\n    public func petition(_ id: Petition.ID) throws -> Petition {\n        try lapseIfDue(id, at: stamp())\n    }\n\n    /// The petitions still waiting, for one reviewer or for all, oldest first.\n    public func pending(for reviewer: Party.ID? = nil) throws -> [Petition] {\n        try sweep()\n        return try store.all().filter { petition in\n            petition.standing == .pending && (reviewer.map { petition.reviewer($0) != nil } ?? true)\n        }\n    }\n\n    /// Every petition, oldest first.\n    public func petitions() throws -> [Petition] {\n        try store.all()\n    }\n\n    /// Every petition as it changes: submitted, decided, lapsed, withdrawn, released.\n    public func observe() -> AsyncStream<Petition> {\n        let (stream, continuation) = AsyncStream.makeStream(of: Petition.self, bufferingPolicy: .unbounded)\n        let token = UUID()\n        observers[token] = continuation\n        continuation.onTermination = { [weak self] _ in\n            Task { await self?.stopObserving(token) }\n        }\n        return stream\n    }\n\n    /// How many callers are waiting in `release(for:)` (tests check none are left behind).\n    var waiterCount: Int { waiters.values.reduce(0) { $0 + $1.count } }\n\n    // MARK: Internals\n\n    private func lapseIfDue(_ id: Petition.ID, at: Date) throws -> Petition {\n        guard let petition = try store.load(id) else { throw BlessError.unknownPetition(id) }\n        guard let lapsed = petition.lapsed(at: at) else { return petition }\n        try store.save(lapsed)\n        try ledger.append(.expired, petition: id, digest: lapsed.digest, code: lapsed.policy.onLapse.name, at: at)\n        transition(lapsed)\n        return lapsed\n    }\n\n    /// The petition's Release, stamping and logging it the first time it is handed out.\n    private func issue(_ petition: Petition) throws -> Release {\n        if let released = petition.released {\n            guard let release = Release(petition: petition, at: released) else { throw BlessError.notBlessed(petition.id) }\n            return release\n        }\n        var next = petition\n        let at = stamp()\n        next.released = at\n        guard let release = Release(petition: next, at: at) else { throw BlessError.notBlessed(petition.id) }\n        try store.save(next)\n        try ledger.append(.released, petition: next.id, digest: release.digest, code: release.basis.rawValue, at: at)\n        broadcast(next)\n        return release\n    }\n\n    private func transition(_ petition: Petition) {\n        broadcast(petition)\n        if petition.isTerminal { wakeAll(petition.id) }\n    }\n\n    private func broadcast(_ petition: Petition) {\n        for observer in observers.values { observer.yield(petition) }\n    }\n\n    private func stopObserving(_ token: UUID) {\n        observers[token] = nil\n    }\n\n    /// Suspends until the petition changes, the deadline passes, or the caller is cancelled.\n    private func park(_ id: Petition.ID, deadline: Date?) async throws {\n        let token = UUID()\n        guard let deadline else {\n            await wait(id, token)\n            try Task.checkCancellation()\n            return\n        }\n        let delay = max(0, deadline.timeIntervalSince(now()))\n        let sleeper = self.sleeper\n        try await withThrowingTaskGroup(of: Void.self) { group in\n            group.addTask { await self.wait(id, token) }\n            group.addTask { try await sleeper(.milliseconds(Int64((delay * 1000).rounded(.up)))) }\n            _ = try await group.next()\n            group.cancelAll()\n        }\n        try Task.checkCancellation()\n    }\n\n    private func wait(_ id: Petition.ID, _ token: UUID) async {\n        await withTaskCancellationHandler {\n            await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in\n                if Task.isCancelled {\n                    continuation.resume()\n                } else {\n                    waiters[id, default: [:]][token] = continuation\n                }\n            }\n        } onCancel: {\n            Task { await self.wake(id, token) }\n        }\n    }\n\n    private func wake(_ id: Petition.ID, _ token: UUID) {\n        guard let continuation = waiters[id]?.removeValue(forKey: token) else { return }\n        if waiters[id]?.isEmpty == true { waiters[id] = nil }\n        continuation.resume()\n    }\n\n    private func wakeAll(_ id: Petition.ID) {\n        for continuation in (waiters.removeValue(forKey: id) ?? [:]).values { continuation.resume() }\n    }\n}\n"},{"path":"Sources/Bless/Ledger/FileLedgerStore.swift","status":"added","lang":"swift","hunks":[[1,0,1,36]],"header":{"lines":[1,11],"target":"Bless","what":[8,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":54,"scopes":[["C","FileLedgerStore",null,"public final",16,16,[16,48],36,null,-1,0,"a"],["i","init",["url"],"public",20,20,[20,33],24,null,0,0,"a"],["f","append",["_"],"public",26,26,[26,52],30,null,0,0,"a"],["f","all",[],"public",32,32,[32,46],35,null,0,0,"a"]],"old":"","new":"//\n//  FileLedgerStore.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A ledger kept as a JSON-lines file: one event per line, appended and flushed to disk\n//        before the append returns, readable by `jq` and by Ledger.verify from any language.\n//        The file is the owner's only (0600), in a directory that is too (0700).\n//\n\nimport Foundation\nimport Synchronization\n\npublic final class FileLedgerStore: LedgerStore {\n    public let url: URL\n    private let lock = Mutex<Void>(())\n\n    public init(url: URL) throws {\n        self.url = url\n        try PrivateFile.createDirectory(url.deletingLastPathComponent())\n        try PrivateFile.touch(url)\n    }\n\n    public func append(_ event: LedgerEvent) throws {\n        var line = try JSONCoding.encoder().encode(event)\n        line.append(0x0A)\n        try lock.withLock { _ in try PrivateFile.append(line, to: url) }\n    }\n\n    public func all() throws -> [LedgerEvent] {\n        let data = try lock.withLock { _ in try PrivateFile.read(url) }\n        return try Ledger.events(fromJSONLines: data)\n    }\n}\n"},{"path":"Sources/Bless/Ledger/Ledger.swift","status":"added","lang":"swift","hunks":[[1,0,1,103]],"header":{"lines":[1,14],"target":"Bless","what":[8,11],"pin":[12,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":58,"scopes":[["C","Ledger",null,"public final",19,19,[19,36],103,null,-1,0,"a"],["S","Head",null,"private",20,20,[20,34],23,null,0,0,"a"],["i","init",[],"public",29,29,[29,18],32,[28,28],0,0,"a"],["i","init",["store"],"public",35,35,[35,47],39,[34,34],0,0,"a"],["f","append",["_","petition","actor","digest","code","at"],"public",42,43,[44,76],52,[41,41],0,0,"a"],["f","events",[],"public",55,55,[55,49],57,[54,54],0,0,"a"],["f","events",["for"],"public",60,60,[60,74],62,[59,59],0,0,"a"],["f","verify",[],"public",65,66,[66,39],68,[64,64],0,0,"a"],["f","verify",["_"],"public static",71,72,[72,69],83,[70,70],0,0,"a"],["f","jsonLines",[],"public",86,86,[86,43],94,[85,85],0,0,"a"],["f","events",["fromJSONLines"],"public static",97,97,[97,80],102,[96,96],0,0,"a"]],"old":"","new":"//\n//  Ledger.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The append-only, hash-chained audit log of every petition's life. `append` numbers the\n//        event, links it to the last hash and writes it; `verify` walks the chain and names the\n//        first event that does not fit (a changed byte, a dropped line, a swapped pair).\n//        `jsonLines()` exports it; `Ledger.verify(_:)` checks an export on its own.\n//  PIN:  The first event's `previous` is 32 zero bytes; seq starts at 1. A Ledger reopened over\n//        a file picks up the chain where it ended.\n//\n\nimport Foundation\nimport Synchronization\n\npublic final class Ledger: Sendable {\n    private struct Head: Sendable {\n        var seq: Int\n        var hash: Sha256\n    }\n\n    private let store: any LedgerStore\n    private let head: Mutex<Head>\n\n    /// A ledger in memory.\n    public init() {\n        self.store = MemoryLedgerStore()\n        self.head = Mutex(Head(seq: 0, hash: .zero))\n    }\n\n    /// A ledger over a store, continuing whatever chain it holds.\n    public init(store: any LedgerStore) throws {\n        self.store = store\n        let last = try store.all().last\n        self.head = Mutex(Head(seq: last?.seq ?? 0, hash: last?.hash ?? .zero))\n    }\n\n    /// Writes the next event and returns it.\n    @discardableResult\n    public func append(_ kind: LedgerEvent.Kind, petition: Petition.ID, actor: Party.ID? = nil, digest: Sha256? = nil,\n                       code: String? = nil, at: Date) throws -> LedgerEvent {\n        try head.withLock { head in\n            let event = LedgerEvent(seq: head.seq + 1, at: at, kind: kind, petitionID: petition, actor: actor,\n                                    digest: digest, code: code, previous: head.hash)\n            try store.append(event)\n            head = Head(seq: event.seq, hash: event.hash)\n            return event\n        }\n    }\n\n    /// Every event, oldest first.\n    public func events() throws -> [LedgerEvent] {\n        try store.all()\n    }\n\n    /// The events concerning one petition.\n    public func events(for petition: Petition.ID) throws -> [LedgerEvent] {\n        try store.all().filter { $0.petitionID == petition }\n    }\n\n    /// The number of events, or `.ledgerTampered(seq:)` at the first that breaks the chain.\n    @discardableResult\n    public func verify() throws -> Int {\n        try Self.verify(try store.all())\n    }\n\n    /// The same check over events from anywhere (an export, another store).\n    @discardableResult\n    public static func verify(_ events: [LedgerEvent]) throws -> Int {\n        var previous = Sha256.zero\n        for (index, event) in events.enumerated() {\n            let expected = index + 1\n            guard event.seq == expected else { throw BlessError.ledgerTampered(seq: expected) }\n            guard event.previous == previous, event.hash == event.recomputedHash else {\n                throw BlessError.ledgerTampered(seq: event.seq)\n            }\n            previous = event.hash\n        }\n        return events.count\n    }\n\n    /// The ledger as JSON lines, one event per line.\n    public func jsonLines() throws -> Data {\n        let encoder = JSONCoding.encoder()\n        var out = Data()\n        for event in try store.all() {\n            out.append(try encoder.encode(event))\n            out.append(0x0A)\n        }\n        return out\n    }\n\n    /// Events from JSON lines (blank lines are skipped).\n    public static func events(fromJSONLines data: Data) throws -> [LedgerEvent] {\n        let decoder = JSONCoding.decoder()\n        return try data.split(separator: 0x0A).filter { !$0.allSatisfy { $0 == 0x20 || $0 == 0x0D } }.map {\n            try decoder.decode(LedgerEvent.self, from: Data($0))\n        }\n    }\n}\n"},{"path":"Sources/Bless/Ledger/LedgerEvent.swift","status":"added","lang":"swift","hunks":[[1,0,1,78]],"header":{"lines":[1,16],"target":"Bless","what":[8,11],"pin":[12,15],"in":null,"out":null,"style":"swift"},"marks":[],"first":69,"scopes":[["S","LedgerEvent",null,"public",20,20,[20,56],78,null,-1,0,"a"],["E","Kind",null,"public",21,21,[21,62],42,null,0,0,"a",["submitted","viewed","decided","blessed","withheld","expired","withdrawn","released","dispatched","failed"]],["i","init",["seq","at","kind","petitionID","actor","digest","code","previous"],"",56,56,[57,27],68,null,0,0,"a"],["v","canonicalBytes",null,"public",71,71,[71,36],74,[70,70],0,0,"a"],["v","recomputedHash",null,"public",77,77,[77,38],77,[76,76],0,8,"a"]],"old":"","new":"//\n//  LedgerEvent.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: One line of the audit log: what happened (kind), to which petition, by whom, to which\n//        text (digest), with which coded outcome, and when. Each event's hash covers its fields\n//        and the previous event's hash, so changing, dropping or reordering any event breaks\n//        every hash after it.\n//  PIN:  No content and no free text, ever: a text appears only as its SHA-256, a ruling or an\n//        error only as its code name. A withholding reason like a test result would otherwise\n//        land in a log every auditor reads. PackageLayeringTests checks that Ledger/ never\n//        touches a message's content.\n//\n\nimport Foundation\n\npublic struct LedgerEvent: Codable, Sendable, Equatable {\n    public enum Kind: String, Codable, Sendable, CaseIterable {\n        /// A draft was held as a petition.\n        case submitted\n        /// A reviewer opened it.\n        case viewed\n        /// A reviewer gave a verdict (code: the ruling's kind).\n        case decided\n        /// The quorum was met.\n        case blessed\n        /// A reviewer withheld it.\n        case withheld\n        /// The deadline passed (code: the policy's lapse).\n        case expired\n        /// The host withdrew it before a decision.\n        case withdrawn\n        /// The Gate first handed out its Release (code: the release's basis).\n        case released\n        /// The host delivered the Release.\n        case dispatched\n        /// Delivering the Release failed (code: the error's code).\n        case failed\n    }\n\n    public let seq: Int\n    public let at: Date\n    public let kind: Kind\n    public let petitionID: Petition.ID\n    public let actor: Party.ID?\n    public let digest: Sha256?\n    /// A ruling kind, a lapse, a release basis or an error code: a name from Bless's own\n    /// vocabulary, never free text.\n    public let code: String?\n    public let previous: Sha256\n    public let hash: Sha256\n\n    init(seq: Int, at: Date, kind: Kind, petitionID: Petition.ID, actor: Party.ID?, digest: Sha256?, code: String?,\n         previous: Sha256) {\n        self.seq = seq\n        self.at = Canonical.stamp(at)\n        self.kind = kind\n        self.petitionID = petitionID\n        self.actor = actor\n        self.digest = digest\n        self.code = code\n        self.previous = previous\n        self.hash = .of(Canonical.event(seq: seq, at: self.at, kind: kind, petitionID: petitionID, actor: actor,\n                                        digest: digest, code: code, previous: previous))\n    }\n\n    /// The bytes the hash covers (Canonical, `bless/event/1`).\n    public var canonicalBytes: Data {\n        Canonical.event(seq: seq, at: at, kind: kind, petitionID: petitionID, actor: actor, digest: digest, code: code,\n                        previous: previous)\n    }\n\n    /// The hash these fields should have; differs from `hash` when the event was changed.\n    public var recomputedHash: Sha256 { .of(canonicalBytes) }\n}\n"},{"path":"Sources/Bless/Ledger/LedgerStore.swift","status":"added","lang":"swift","hunks":[[1,0,1,34]],"header":{"lines":[1,12],"target":"Bless","what":[8,9],"pin":[10,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":74,"scopes":[["P","LedgerStore",null,"public",17,17,[17,38],20,null,-1,0,"a"],["f","append",["_"],"",18,18,null,18,null,0,1,"a"],["f","all",[],"",19,19,null,19,null,0,1,"a"],["C","MemoryLedgerStore",null,"public final",22,22,[22,50],34,null,-1,0,"a"],["i","init",[],"public",25,25,[25,18],25,null,3,8,"a"],["f","append",["_"],"public",27,27,[27,52],29,null,3,0,"a"],["f","all",[],"public",31,31,[31,46],33,null,3,0,"a"]],"old":"","new":"//\n//  LedgerStore.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Where a ledger's events are kept: append one, read them all, in order. In memory here;\n//        FileLedgerStore keeps them as JSON lines.\n//  PIN:  Synchronous on purpose: the Gate calls it inside actor methods that must not suspend,\n//        so each transition and its ledger line happen as one step.\n//\n\nimport Foundation\nimport Synchronization\n\npublic protocol LedgerStore: Sendable {\n    func append(_ event: LedgerEvent) throws\n    func all() throws -> [LedgerEvent]\n}\n\npublic final class MemoryLedgerStore: LedgerStore {\n    private let events = Mutex<[LedgerEvent]>([])\n\n    public init() {}\n\n    public func append(_ event: LedgerEvent) throws {\n        events.withLock { $0.append(event) }\n    }\n\n    public func all() throws -> [LedgerEvent] {\n        events.withLock { $0 }\n    }\n}\n"},{"path":"Sources/Bless/Parties/Party.swift","status":"added","lang":"swift","hunks":[[1,0,1,40]],"header":{"lines":[1,12],"target":"Bless","what":[8,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":81,"scopes":[["S","Party",null,"public",16,16,[16,63],40,null,-1,0,"a"],["S","ID",null,"public",17,17,[17,121],23,null,0,0,"a"],["i","init",["rawValue"],"public",19,19,[19,38],19,null,1,8,"a"],["i","init",["_"],"public",20,20,[20,40],20,null,1,8,"a"],["i","init",["stringLiteral"],"public",21,21,[21,49],21,null,1,8,"a"],["v","description",null,"public",22,22,[22,39],22,null,1,8,"a"],["i","init",["id","displayName","verifyingKey"],"public",30,30,[30,72],34,null,0,0,"a"],["v","fingerprint",null,"public",37,37,[37,36],39,[36,36],0,0,"a"]],"old":"","new":"//\n//  Party.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A person in a conversation: the recipient of a reply, or a reviewer of it. A reviewer\n//        carries the public half of their signing key, which the Gate checks every verdict's\n//        seal against. The role is not stored here: the same doctor reviews one petition and may\n//        receive another, so each Petition names its recipient and its reviewers.\n//\n\nimport Foundation\n\npublic struct Party: Codable, Sendable, Hashable, Identifiable {\n    public struct ID: RawRepresentable, Hashable, Codable, Sendable, CustomStringConvertible, ExpressibleByStringLiteral {\n        public let rawValue: String\n        public init(rawValue: String) { self.rawValue = rawValue }\n        public init(_ rawValue: String) { self.rawValue = rawValue }\n        public init(stringLiteral value: String) { self.rawValue = value }\n        public var description: String { rawValue }\n    }\n\n    public let id: ID\n    public var displayName: String\n    /// The raw 32-byte Curve25519 (Ed25519) public key a reviewer's seals verify against.\n    public var verifyingKey: Data?\n\n    public init(id: ID, displayName: String, verifyingKey: Data? = nil) {\n        self.id = id\n        self.displayName = displayName\n        self.verifyingKey = verifyingKey\n    }\n\n    /// The first 16 hex digits of the SHA-256 of the verifying key, for a person to read aloud.\n    public var fingerprint: String? {\n        verifyingKey.map { String(Sha256.of($0).hex.prefix(16)) }\n    }\n}\n"},{"path":"Sources/Bless/Parties/ReviewerIdentity.swift","status":"added","lang":"swift","hunks":[[1,0,1,57]],"header":{"lines":[1,15],"target":"Bless","what":[8,10],"pin":[11,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":89,"scopes":[["S","ReviewerIdentity",null,"public",20,20,[20,41],57,null,-1,0,"a"],["i","init",["id","displayName"],"public",27,27,[27,51],31,[26,26],0,0,"a"],["i","init",["id","displayName","privateKey"],"public",34,34,[34,80],43,[33,33],0,0,"a"],["v","verifyingKey",null,"public",46,46,[46,34],46,[45,45],0,8,"a"],["v","fingerprint",null,"public",49,49,[49,35],49,[48,48],0,8,"a"],["f","verdict",["_","on","note","issued"],"public",52,52,[52,127],56,[51,51],0,0,"a"]],"old":"","new":"//\n//  ReviewerIdentity.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A reviewer and their private signing key, on the reviewer's own device: it turns a\n//        ruling on a petition into a sealed Verdict, which the Gate verifies against the public\n//        key the reviewer's Party carries. The Gate never needs the private key.\n//  PIN:  The key is held as its 32 raw bytes (Curve25519.Signing's rawRepresentation), so the\n//        identity is plainly Sendable and the host can keep those bytes in its keychain.\n//        CryptoKit's Ed25519 signatures are randomized: two seals over the same verdict differ,\n//        and both verify.\n//\n\nimport CryptoKit\nimport Foundation\n\npublic struct ReviewerIdentity: Sendable {\n    /// The reviewer as petitions name them, with the verifying key.\n    public let party: Party\n    /// The raw 32-byte private key. Keep it where the host keeps secrets.\n    public let privateKey: Data\n\n    /// A reviewer with a fresh key.\n    public init(id: Party.ID, displayName: String) {\n        let key = Curve25519.Signing.PrivateKey()\n        self.privateKey = key.rawRepresentation\n        self.party = Party(id: id, displayName: displayName, verifyingKey: key.publicKey.rawRepresentation)\n    }\n\n    /// A reviewer whose key was kept from before.\n    public init(id: Party.ID, displayName: String, privateKey raw: Data) throws {\n        let key: Curve25519.Signing.PrivateKey\n        do {\n            key = try Curve25519.Signing.PrivateKey(rawRepresentation: raw)\n        } catch {\n            throw BlessError.invalidPolicy(\"a reviewer's private key is 32 raw bytes\")\n        }\n        self.privateKey = key.rawRepresentation\n        self.party = Party(id: id, displayName: displayName, verifyingKey: key.publicKey.rawRepresentation)\n    }\n\n    /// The raw 32-byte public key.\n    public var verifyingKey: Data { party.verifyingKey ?? Data() }\n\n    /// The verifying key's fingerprint.\n    public var fingerprint: String { party.fingerprint ?? \"\" }\n\n    /// The ruling, sealed: a Verdict on the petition's current text, signed with this key.\n    public func verdict(_ ruling: Ruling, on petition: Petition, note: String? = nil, issued: Date = Date()) throws -> Verdict {\n        let unsigned = Verdict(petitionID: petition.id, reviewer: party.id, ruling: ruling,\n                               digest: petition.digest, note: note, issued: issued)\n        return try Seal.sign(unsigned, privateKey: privateKey)\n    }\n}\n"},{"path":"Sources/Bless/Pattern/Blessed.swift","status":"added","lang":"swift","hunks":[[1,0,1,117]],"header":{"lines":[1,17],"target":"Bless","what":[8,13],"pin":[14,16],"in":null,"out":null,"style":"swift"},"marks":[],"first":95,"scopes":[["S","Routing",null,"public",22,22,[22,32],34,[21,21],-1,0,"a"],["i","init",["conversationID","recipient","reviewers","policy"],"public",28,28,[28,105],33,null,0,0,"a"],["S","BlessedResponse",null,"public",37,37,[37,40],43,[36,36],-1,0,"a"],["S","Blessed",null,"public",45,45,[45,70],117,null,-1,0,"a"],["i","init",["upstream","gate","held","route"],"public",56,56,[57,76],62,[51,55],3,0,"a"],["v","name",null,"public",64,64,[64,28],64,null,3,8,"a"],["f","blessed",["_"],"public",67,67,[67,80],71,[66,66],3,0,"a"],["f","complete",["_"],"public",74,74,[74,78],76,[73,73],3,0,"a"],["f","stream",["_"],"public",79,79,[79,92],98,[78,78],3,0,"a"],["f","hold",["_","for","routing","announce"],"private",100,100,[101,103],116,null,3,0,"a"]],"old":"","new":"//\n//  Blessed.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The pattern, as one InferenceProvider. Wrap a model in Blessed and every reply it\n//        writes is held at the Gate as a petition; `complete` returns only once a reviewer has\n//        blessed (or amended) it, with the blessed text in place of the model's. A host that\n//        calls `model.complete(request)` today calls `blessed.complete(request)` instead and\n//        changes nothing else. `route` says, per request, whose conversation it is, who\n//        receives the reply, who reviews it and under which policy.\n//  PIN:  Nothing streams until it is blessed: `stream` reads the model's stream to its end,\n//        holds the whole reply, sends one delta carrying only the petition's id, waits, then\n//        sends the blessed text. Cancelling the consumer cancels the wait, not the review.\n//\n\nimport Foundation\n\n/// Who a request's reply is for and who must bless it.\npublic struct Routing: Sendable {\n    public var conversationID: String\n    public var recipient: Party\n    public var reviewers: [Party]\n    public var policy: Policy\n\n    public init(conversationID: String, recipient: Party, reviewers: [Party], policy: Policy = Policy()) {\n        self.conversationID = conversationID\n        self.recipient = recipient\n        self.reviewers = reviewers\n        self.policy = policy\n    }\n}\n\n/// A blessed reply with the record behind it.\npublic struct BlessedResponse: Sendable {\n    /// The reply as the host should deliver it: the Release's text under the model's id.\n    public var response: ChatResponse\n    /// The petition, as decided.\n    public var petition: Petition\n    public var release: Release\n}\n\npublic struct Blessed<Upstream: InferenceProvider>: InferenceProvider {\n    public let upstream: Upstream\n    public let gate: Gate\n    private let route: @Sendable (ChatRequest) throws -> Routing\n    private let held: (@Sendable (Petition) -> Void)?\n\n    /// - Parameters:\n    ///   - upstream: the model whose replies are held.\n    ///   - gate: where they wait.\n    ///   - held: called with each petition as soon as it is held (page the reviewer here).\n    ///   - route: the conversation, recipient, reviewers and policy for a request.\n    public init(upstream: Upstream, gate: Gate, held: (@Sendable (Petition) -> Void)? = nil,\n                route: @escaping @Sendable (ChatRequest) throws -> Routing) {\n        self.upstream = upstream\n        self.gate = gate\n        self.held = held\n        self.route = route\n    }\n\n    public var name: String { \"blessed(\\(upstream.name))\" }\n\n    /// The blessed reply, with its petition and release.\n    public func blessed(_ request: ChatRequest) async throws -> BlessedResponse {\n        let routing = try route(request)\n        let draft = try await upstream.complete(request)\n        return try await hold(draft, for: request, routing: routing)\n    }\n\n    /// The reply, once blessed: the Release's text under the model's id.\n    public func complete(_ request: ChatRequest) async throws -> ChatResponse {\n        try await blessed(request).response\n    }\n\n    /// One `held` delta, then the blessed text and the finish. Nothing of the draft is streamed.\n    public func stream(_ request: ChatRequest) -> AsyncThrowingStream<ChatDelta, any Error> {\n        AsyncThrowingStream { continuation in\n            let task = Task {\n                do {\n                    let routing = try route(request)\n                    let draft = try await upstream.stream(request).assembled(model: request.model)\n                    let out = try await hold(draft, for: request, routing: routing) { petition in\n                        continuation.yield(ChatDelta(held: petition.id))\n                    }\n                    continuation.yield(ChatDelta(role: .assistant, content: out.response.message.content,\n                                                 id: out.response.id, model: out.response.model))\n                    continuation.yield(ChatDelta(finishReason: out.response.finishReason ?? .stop))\n                    continuation.finish()\n                } catch {\n                    continuation.finish(throwing: error)\n                }\n            }\n            continuation.onTermination = { _ in task.cancel() }\n        }\n    }\n\n    private func hold(_ draft: ChatResponse, for request: ChatRequest, routing: Routing,\n                      announce: (@Sendable (Petition) -> Void)? = nil) async throws -> BlessedResponse {\n        let petition = try await gate.submit(\n            Draft(conversationID: routing.conversationID, context: request.messages,\n                  proposed: .assistant(draft.message.content),\n                  provenance: Provenance(provider: upstream.name, model: draft.model, requestID: draft.id,\n                                         created: draft.created ?? Date())),\n            to: routing.recipient, reviewers: routing.reviewers, policy: routing.policy)\n        held?(petition)\n        announce?(petition)\n        let release = try await gate.release(for: petition.id)\n        let decided = try await gate.petition(petition.id)\n        let response = ChatResponse(id: draft.id, model: draft.model, message: release.message,\n                                    finishReason: release.basis == .blessed ? draft.finishReason : .stop,\n                                    usage: draft.usage, created: draft.created)\n        return BlessedResponse(response: response, petition: decided, release: release)\n    }\n}\n"},{"path":"Sources/Bless/Petition/Draft.swift","status":"added","lang":"swift","hunks":[[1,0,1,48]],"header":{"lines":[1,11],"target":"Bless","what":[8,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":105,"scopes":[["S","Provenance",null,"public",16,16,[16,55],28,[15,15],-1,0,"a"],["i","init",["provider","model","requestID","created"],"public",22,22,[22,99],27,null,0,0,"a"],["S","Draft",null,"public",30,30,[30,41],48,null,-1,0,"a"],["i","init",["conversationID","context","proposed","provenance"],"public",39,39,[39,111],44,null,2,0,"a"],["v","digest",null,"public",47,47,[47,30],47,[46,46],2,8,"a"]],"old":"","new":"//\n//  Draft.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What a host hands the Gate: the reply the model proposes, the conversation it answers,\n//        and where it came from. The Gate keeps only as much of the conversation as the policy's\n//        context window allows, and never a system message.\n//\n\nimport Foundation\n\n/// Who wrote a draft: the provider and model, the provider's id for the reply, and when.\npublic struct Provenance: Codable, Sendable, Equatable {\n    public var provider: String\n    public var model: String\n    public var requestID: String?\n    public var created: Date\n\n    public init(provider: String, model: String, requestID: String? = nil, created: Date = Date()) {\n        self.provider = provider\n        self.model = model\n        self.requestID = requestID\n        self.created = Canonical.stamp(created)\n    }\n}\n\npublic struct Draft: Sendable, Equatable {\n    /// The host's id for the conversation, so a reviewer can see one patient's thread together.\n    public var conversationID: String\n    /// The conversation so far, oldest first (the Gate trims it to the policy's window).\n    public var context: [ChatMessage]\n    /// The reply the model proposes. Its role must be `.assistant`.\n    public var proposed: ChatMessage\n    public var provenance: Provenance\n\n    public init(conversationID: String, context: [ChatMessage], proposed: ChatMessage, provenance: Provenance) {\n        self.conversationID = conversationID\n        self.context = context\n        self.proposed = proposed\n        self.provenance = provenance\n    }\n\n    /// The SHA-256 of the proposed text.\n    public var digest: Sha256 { .of(proposed.content) }\n}\n"},{"path":"Sources/Bless/Petition/Petition.swift","status":"added","lang":"swift","hunks":[[1,0,1,168]],"header":{"lines":[1,20],"target":"Bless","what":[8,19],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[[76,"Derived"],[116,"The rules"]],"first":110,"scopes":[["S","Petition",null,"public",24,24,[24,67],168,null,-1,0,"a"],["S","ID",null,"public",25,25,[25,121],33,null,0,0,"a"],["i","init",["rawValue"],"public",27,27,[27,38],27,null,1,8,"a"],["i","init",["_"],"public",28,28,[28,40],28,null,1,8,"a"],["i","init",["stringLiteral"],"public",29,29,[29,49],29,null,1,8,"a"],["i","init",[],"public",31,31,[31,22],31,[30,30],1,8,"a"],["v","description",null,"public",32,32,[32,39],32,null,1,8,"a"],["E","Standing",null,"public",36,36,[36,66],38,[35,35],0,0,"a",["pending","blessed","withheld","expired","withdrawn"]],["i","init",["id","conversationID","context","proposed","provenance","recipient","reviewers","policy","submitted","deadline"],"",58,58,[59,97],74,null,0,0,"a"],["v","message",null,"public",79,79,[79,36],84,[78,78],0,0,"a"],["v","digest",null,"public",87,87,[87,30],87,[86,86],0,8,"a"],["v","amended",null,"public",90,90,[90,29],90,[89,89],0,8,"a"],["v","blessings",null,"public",93,93,[93,36],97,[92,92],0,0,"a"],["v","withholding",null,"public",100,100,[100,37],102,[99,99],0,0,"a"],["v","withheldReason",null,"public",105,105,[105,39],108,[104,104],0,0,"a"],["v","isTerminal",null,"public",110,110,[110,32],110,null,0,8,"a"],["f","reviewer",["_"],"public",112,112,[112,51],114,null,0,0,"a"],["f","applying",["_","at"],"public",119,119,[119,78],150,[118,118],0,0,"a"],["f","lapsed",["at"],"public",154,154,[154,50],161,[152,153],0,0,"a"],["v","fallback",null,"public",164,164,[164,33],167,[163,163],0,0,"a"]],"old":"","new":"//\n//  Petition.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A reply held for review: the proposed text, the conversation the policy lets reviewers\n//        see, who it is for, who may rule on it, and every verdict so far. What the recipient\n//        would get (`message`), its digest and its blessings are derived from those, never\n//        stored beside them. The rules that move a petition are pure functions here, so they are\n//        tested without a Gate:\n//          withhold wins          any withholding before the petition is blessed ends it\n//          blessings bind to text only verdicts endorsing the current digest count; an amendment\n//                                 makes a new digest, so the count starts again with the amender\n//          no stale verdicts      a verdict on a text that is no longer current is refused\n//          one blessing per text  a reviewer blesses a text once; a withholding is always heard\n//          late is refused        a decided, lapsed or withdrawn petition accepts nothing\n//          a lapse is the policy's at the deadline the policy, not a reviewer, decides\n//\n\nimport Foundation\n\npublic struct Petition: Codable, Sendable, Equatable, Identifiable {\n    public struct ID: RawRepresentable, Hashable, Codable, Sendable, CustomStringConvertible, ExpressibleByStringLiteral {\n        public let rawValue: String\n        public init(rawValue: String) { self.rawValue = rawValue }\n        public init(_ rawValue: String) { self.rawValue = rawValue }\n        public init(stringLiteral value: String) { self.rawValue = value }\n        /// A fresh random id.\n        public init() { self.rawValue = UUID().uuidString.lowercased() }\n        public var description: String { rawValue }\n    }\n\n    /// Where a petition stands. Every case but `pending` is final.\n    public enum Standing: String, Codable, Sendable, CaseIterable {\n        case pending, blessed, withheld, expired, withdrawn\n    }\n\n    public let id: ID\n    public let conversationID: String\n    /// The conversation as the policy lets reviewers see it (no system messages).\n    public let context: [ChatMessage]\n    /// The model's reply, as proposed. It never changes; amendments live in `verdicts`.\n    public let proposed: ChatMessage\n    public let provenance: Provenance\n    public let recipient: Party\n    public let reviewers: [Party]\n    public let policy: Policy\n    public let submitted: Date\n    public let deadline: Date?\n    public internal(set) var verdicts: [Verdict]\n    public internal(set) var standing: Standing\n    public internal(set) var decided: Date?\n    /// When the Gate first handed out this petition's Release.\n    public internal(set) var released: Date?\n\n    init(id: ID, conversationID: String, context: [ChatMessage], proposed: ChatMessage, provenance: Provenance,\n         recipient: Party, reviewers: [Party], policy: Policy, submitted: Date, deadline: Date?) {\n        self.id = id\n        self.conversationID = conversationID\n        self.context = context\n        self.proposed = proposed\n        self.provenance = provenance\n        self.recipient = recipient\n        self.reviewers = reviewers\n        self.policy = policy\n        self.submitted = submitted\n        self.deadline = deadline\n        self.verdicts = []\n        self.standing = .pending\n        self.decided = nil\n        self.released = nil\n    }\n\n    // MARK: Derived\n\n    /// What the recipient would get: the latest amendment, else the proposed text.\n    public var message: ChatMessage {\n        for verdict in verdicts.reversed() {\n            if case .amend(let content) = verdict.ruling { return .assistant(content) }\n        }\n        return .assistant(proposed.content)\n    }\n\n    /// The SHA-256 of `message`.\n    public var digest: Sha256 { .of(message.content) }\n\n    /// Whether a reviewer changed the text.\n    public var amended: Bool { message.content != proposed.content }\n\n    /// The verdicts that endorse the current text, one per reviewer.\n    public var blessings: [Verdict] {\n        let current = digest\n        var seen: Set<Party.ID> = []\n        return verdicts.filter { $0.endorsed == current && seen.insert($0.reviewer).inserted }\n    }\n\n    /// The withholding that ended the petition, if one did.\n    public var withholding: Verdict? {\n        verdicts.first { $0.ruling.kind == .withhold }\n    }\n\n    /// The reviewer's withholding reason, when a reviewer withheld it.\n    public var withheldReason: String? {\n        if case .withhold(let reason)? = withholding?.ruling { return reason }\n        return nil\n    }\n\n    public var isTerminal: Bool { standing != .pending }\n\n    public func reviewer(_ id: Party.ID) -> Party? {\n        reviewers.first { $0.id == id }\n    }\n\n    // MARK: The rules\n\n    /// The petition with this verdict applied, or the rule it breaks. `now` decides lateness.\n    public func applying(_ verdict: Verdict, at now: Date) throws -> Petition {\n        guard standing == .pending else { throw BlessError.alreadyDecided(id, standing) }\n        guard verdict.petitionID == id else { throw BlessError.unknownPetition(verdict.petitionID) }\n        guard reviewer(verdict.reviewer) != nil else { throw BlessError.notAReviewer(verdict.reviewer) }\n        if let deadline, now >= deadline, policy.onLapse != .hold { throw BlessError.expired(id) }\n        let current = digest\n        guard verdict.digest == current else { throw BlessError.staleVerdict(expected: current, saw: verdict.digest) }\n\n        var next = self\n        switch verdict.ruling {\n        case .withhold:\n            next.verdicts.append(verdict)\n            next.standing = .withheld\n            next.decided = Canonical.stamp(now)\n            return next\n        case .amend(let content) where Sha256.of(content) != current:\n            guard policy.allowsAmendment else { throw BlessError.amendmentNotAllowed }\n            guard !content.isEmpty else { throw BlessError.invalidDraft(\"an amendment cannot be empty\") }\n            next.verdicts.append(verdict)\n        case .bless, .amend:\n            // An amendment that leaves the text as it is reads as a blessing of it.\n            guard !blessings.contains(where: { $0.reviewer == verdict.reviewer }) else {\n                throw BlessError.duplicateVerdict(verdict.reviewer)\n            }\n            next.verdicts.append(verdict)\n        }\n        if next.blessings.count >= policy.quorum {\n            next.standing = .blessed\n            next.decided = Canonical.stamp(now)\n        }\n        return next\n    }\n\n    /// The petition after its deadline, when the deadline has passed and the policy lets it\n    /// lapse; nil when it is not due, already final, or the policy holds.\n    public func lapsed(at now: Date) -> Petition? {\n        guard standing == .pending, let deadline, now >= deadline else { return nil }\n        if case .hold = policy.onLapse { return nil }\n        var next = self\n        next.standing = .expired\n        next.decided = Canonical.stamp(now)\n        return next\n    }\n\n    /// The fixed text a lapsed petition releases, when its policy names one.\n    public var fallback: String? {\n        if case .releaseFallback(let text) = policy.onLapse, standing == .expired { return text }\n        return nil\n    }\n}\n"},{"path":"Sources/Bless/Petition/Policy.swift","status":"added","lang":"swift","hunks":[[1,0,1,126]],"header":{"lines":[1,15],"target":"Bless","what":[8,11],"pin":[12,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":130,"scopes":[["S","Policy",null,"public",19,19,[19,42],90,null,-1,0,"a"],["E","Lapse",null,"public",21,21,[21,43],37,[20,20],0,0,"a",["hold","withhold","releaseFallback"]],["v","name",null,"public",30,30,[30,32],36,null,1,0,"a"],["i","init",["quorum","deadline","onLapse","allowsAmendment","contextWindow","requiresSeal"],"public",47,47,[48,70],55,null,0,0,"a"],["f","validate",["reviewers"],"public",58,58,[58,52],76,[57,57],0,0,"a"],["f","trimmed",["_"],"public",80,80,[80,67],84,[78,79],0,0,"a"],["v","deadlineInterval",null,"",87,87,[87,40],89,[86,86],0,0,"a"],["X","Policy",null,"",92,92,[92,26],126,null,-1,0,"a"],["E","CodingKeys",null,"private",93,93,[93,47],95,null,7,0,"a",["quorum","deadlineMilliseconds","onLapse","fallback","allowsAmendment","contextWindow","requiresSeal"]],["i","init",["from"],"public",97,97,[97,50],111,null,7,0,"a"],["f","encode",["to"],"public",113,113,[113,55],125,null,7,0,"a"]],"old":"","new":"//\n//  Policy.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The rules one petition is held under: how many reviewers must bless it (quorum), how\n//        long they have (deadline) and what happens when it passes (onLapse), whether a reviewer\n//        may change the text (allowsAmendment), how much of the conversation the reviewer sees\n//        and the store keeps (contextWindow), and whether verdicts must be sealed.\n//  PIN:  The defaults are the owner's: one reviewer, no deadline, a lapse holds (nothing\n//        unreviewed is ever released by default), amendments allowed, the whole conversation\n//        minus system messages, seals required. JSON writes the deadline as whole milliseconds.\n//\n\nimport Foundation\n\npublic struct Policy: Sendable, Equatable {\n    /// What happens to a petition still pending at its deadline.\n    public enum Lapse: Sendable, Equatable {\n        /// Nothing: it stays pending until a reviewer rules. The default.\n        case hold\n        /// It expires, and nothing is released.\n        case withhold\n        /// It expires, and this fixed text is released in its place (a safe holding message,\n        /// such as \"Your care team will reply soon\"). Never the model's draft.\n        case releaseFallback(String)\n\n        public var name: String {\n            switch self {\n            case .hold: \"hold\"\n            case .withhold: \"withhold\"\n            case .releaseFallback: \"releaseFallback\"\n            }\n        }\n    }\n\n    public var quorum: Int\n    public var deadline: Duration?\n    public var onLapse: Lapse\n    public var allowsAmendment: Bool\n    /// How many of the latest user and assistant messages the petition keeps; nil keeps them all.\n    public var contextWindow: Int?\n    public var requiresSeal: Bool\n\n    public init(quorum: Int = 1, deadline: Duration? = nil, onLapse: Lapse = .hold, allowsAmendment: Bool = true,\n                contextWindow: Int? = nil, requiresSeal: Bool = true) {\n        self.quorum = quorum\n        self.deadline = deadline\n        self.onLapse = onLapse\n        self.allowsAmendment = allowsAmendment\n        self.contextWindow = contextWindow\n        self.requiresSeal = requiresSeal\n    }\n\n    /// Throws `.invalidPolicy` unless these reviewers can meet the policy.\n    public func validate(reviewers: [Party]) throws {\n        guard !reviewers.isEmpty else { throw BlessError.invalidPolicy(\"a petition needs at least one reviewer\") }\n        guard Set(reviewers.map(\\.id)).count == reviewers.count else {\n            throw BlessError.invalidPolicy(\"each reviewer may be named once\")\n        }\n        guard quorum >= 1, quorum <= reviewers.count else {\n            throw BlessError.invalidPolicy(\"quorum \\(quorum) of \\(reviewers.count) reviewers\")\n        }\n        if let deadline, deadline <= .zero { throw BlessError.invalidPolicy(\"the deadline must be in the future\") }\n        if let contextWindow, contextWindow < 0 { throw BlessError.invalidPolicy(\"the context window cannot be negative\") }\n        if case .releaseFallback(let text) = onLapse, text.isEmpty {\n            throw BlessError.invalidPolicy(\"a fallback release needs its text\")\n        }\n        if requiresSeal {\n            for reviewer in reviewers where reviewer.verifyingKey?.count != 32 {\n                throw BlessError.sealRequired(reviewer.id)\n            }\n        }\n    }\n\n    /// The conversation as the petition keeps it: no system messages, and only the latest\n    /// `contextWindow` of the rest.\n    public func trimmed(_ context: [ChatMessage]) -> [ChatMessage] {\n        let turns = context.filter { $0.role != .system }\n        guard let contextWindow else { return turns }\n        return Array(turns.suffix(contextWindow))\n    }\n\n    /// The deadline in seconds, as a TimeInterval.\n    var deadlineInterval: TimeInterval? {\n        deadline.map { Double($0.components.seconds) + Double($0.components.attoseconds) / 1e18 }\n    }\n}\n\nextension Policy: Codable {\n    private enum CodingKeys: String, CodingKey {\n        case quorum, deadlineMilliseconds, onLapse, fallback, allowsAmendment, contextWindow, requiresSeal\n    }\n\n    public init(from decoder: any Decoder) throws {\n        let c = try decoder.container(keyedBy: CodingKeys.self)\n        quorum = try c.decode(Int.self, forKey: .quorum)\n        deadline = try c.decodeIfPresent(Int64.self, forKey: .deadlineMilliseconds).map { .milliseconds($0) }\n        switch try c.decode(String.self, forKey: .onLapse) {\n        case \"hold\": onLapse = .hold\n        case \"withhold\": onLapse = .withhold\n        case \"releaseFallback\": onLapse = .releaseFallback(try c.decode(String.self, forKey: .fallback))\n        case let other:\n            throw DecodingError.dataCorruptedError(forKey: .onLapse, in: c, debugDescription: \"unknown lapse \\(other)\")\n        }\n        allowsAmendment = try c.decode(Bool.self, forKey: .allowsAmendment)\n        contextWindow = try c.decodeIfPresent(Int.self, forKey: .contextWindow)\n        requiresSeal = try c.decode(Bool.self, forKey: .requiresSeal)\n    }\n\n    public func encode(to encoder: any Encoder) throws {\n        var c = encoder.container(keyedBy: CodingKeys.self)\n        try c.encode(quorum, forKey: .quorum)\n        if let deadline {\n            let ms = deadline.components.seconds * 1000 + deadline.components.attoseconds / 1_000_000_000_000_000\n            try c.encode(ms, forKey: .deadlineMilliseconds)\n        }\n        try c.encode(onLapse.name, forKey: .onLapse)\n        if case .releaseFallback(let text) = onLapse { try c.encode(text, forKey: .fallback) }\n        try c.encode(allowsAmendment, forKey: .allowsAmendment)\n        try c.encodeIfPresent(contextWindow, forKey: .contextWindow)\n        try c.encode(requiresSeal, forKey: .requiresSeal)\n    }\n}\n"},{"path":"Sources/Bless/Petition/Release.swift","status":"added","lang":"swift","hunks":[[1,0,1,91]],"header":{"lines":[1,13],"target":"Bless","what":[8,12],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":141,"scopes":[["S","Release",null,"public",17,17,[17,52],91,null,-1,0,"a"],["E","Basis",null,"public",18,18,[18,63],25,null,0,0,"a",["blessed","amended","lapsed"]],["i","init",["petition","at"],"",36,36,[36,49],54,[35,35],0,0,"a"],["f","verify",["against"],"public",57,57,[57,58],90,[56,56],0,0,"a"]],"old":"","new":"//\n//  Release.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The only thing a host may deliver to a recipient: the blessed (or amended) message, its\n//        digest, and the sealed verdicts that allowed it; or, for a lapsed petition whose policy\n//        names one, the policy's fixed fallback text with no verdicts. Only the Gate makes one.\n//        `verify(against:)` re-checks it from scratch against the petition: the digest, every\n//        seal, the quorum.\n//\n\nimport Foundation\n\npublic struct Release: Codable, Sendable, Equatable {\n    public enum Basis: String, Codable, Sendable, CaseIterable {\n        /// Blessed as the model wrote it.\n        case blessed\n        /// Blessed after a reviewer changed it.\n        case amended\n        /// The deadline passed; the policy's fallback text, not the model's.\n        case lapsed\n    }\n\n    public let petitionID: Petition.ID\n    public let recipient: Party.ID\n    public let message: ChatMessage\n    public let digest: Sha256\n    public let basis: Basis\n    public let verdicts: [Verdict]\n    public let released: Date\n\n    /// The release a decided petition allows, or nil when it allows none.\n    init?(petition: Petition, at released: Date) {\n        switch petition.standing {\n        case .blessed:\n            self.message = petition.message\n            self.basis = petition.amended ? .amended : .blessed\n            self.verdicts = petition.blessings\n        case .expired:\n            guard let text = petition.fallback else { return nil }\n            self.message = .assistant(text)\n            self.basis = .lapsed\n            self.verdicts = []\n        case .pending, .withheld, .withdrawn:\n            return nil\n        }\n        self.petitionID = petition.id\n        self.recipient = petition.recipient.id\n        self.digest = .of(message.content)\n        self.released = released\n    }\n\n    /// Throws unless this release is exactly what the petition allows.\n    public func verify(against petition: Petition) throws {\n        guard petitionID == petition.id else { throw BlessError.invalidRelease(\"another petition's release\") }\n        guard recipient == petition.recipient.id else { throw BlessError.invalidRelease(\"addressed to someone else\") }\n        guard message.role == .assistant, digest == .of(message.content) else {\n            throw BlessError.invalidRelease(\"the digest does not match the message\")\n        }\n        switch basis {\n        case .lapsed:\n            guard petition.standing == .expired, let text = petition.fallback, message.content == text, verdicts.isEmpty else {\n                throw BlessError.invalidRelease(\"a lapse releases only the policy's fallback\")\n            }\n        case .blessed, .amended:\n            guard petition.standing == .blessed, digest == petition.digest else {\n                throw BlessError.invalidRelease(\"the petition did not bless this text\")\n            }\n            guard (basis == .amended) == petition.amended else { throw BlessError.invalidRelease(\"the basis is wrong\") }\n            var reviewers: Set<Party.ID> = []\n            for verdict in verdicts {\n                guard verdict.petitionID == petition.id, verdict.endorsed == digest else {\n                    throw BlessError.invalidRelease(\"a verdict endorses another text\")\n                }\n                guard let reviewer = petition.reviewer(verdict.reviewer) else { throw BlessError.notAReviewer(verdict.reviewer) }\n                if let key = reviewer.verifyingKey, verdict.signature != nil {\n                    guard Seal.verify(verdict, verifyingKey: key) else { throw BlessError.badSeal(reviewer.id) }\n                } else if petition.policy.requiresSeal {\n                    throw BlessError.sealRequired(reviewer.id)\n                }\n                reviewers.insert(reviewer.id)\n            }\n            guard reviewers.count >= petition.policy.quorum else {\n                throw BlessError.invalidRelease(\"\\(reviewers.count) of \\(petition.policy.quorum) blessings\")\n            }\n        }\n    }\n}\n"},{"path":"Sources/Bless/Petition/Ruling.swift","status":"added","lang":"swift","hunks":[[1,0,1,54]],"header":{"lines":[1,11],"target":"Bless","what":[8,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":145,"scopes":[["E","Ruling",null,"public",15,15,[15,40],31,null,-1,0,"a",["bless","amend","withhold"]],["E","Kind",null,"public",20,20,[20,62],22,null,0,0,"a",["bless","amend","withhold"]],["v","kind",null,"public",24,24,[24,26],30,null,0,0,"a"],["X","Ruling",null,"",33,33,[33,26],54,null,-1,0,"a"],["E","CodingKeys",null,"private",34,34,[34,47],34,null,3,8,"a",[]],["i","init",["from"],"public",36,36,[36,50],43,null,3,0,"a"],["f","encode",["to"],"public",45,45,[45,55],53,null,3,0,"a"]],"old":"","new":"//\n//  Ruling.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: What a reviewer decides about a held reply: bless it as written, amend it (the amended\n//        text is what the recipient gets), or withhold it (nothing is sent; the reason stays in\n//        the petition store for the host's records, never in the ledger).\n//\n\nimport Foundation\n\npublic enum Ruling: Sendable, Equatable {\n    case bless\n    case amend(content: String)\n    case withhold(reason: String)\n\n    public enum Kind: String, Codable, Sendable, CaseIterable {\n        case bless, amend, withhold\n    }\n\n    public var kind: Kind {\n        switch self {\n        case .bless: .bless\n        case .amend: .amend\n        case .withhold: .withhold\n        }\n    }\n}\n\nextension Ruling: Codable {\n    private enum CodingKeys: String, CodingKey { case kind, content, reason }\n\n    public init(from decoder: any Decoder) throws {\n        let c = try decoder.container(keyedBy: CodingKeys.self)\n        switch try c.decode(Kind.self, forKey: .kind) {\n        case .bless: self = .bless\n        case .amend: self = .amend(content: try c.decode(String.self, forKey: .content))\n        case .withhold: self = .withhold(reason: try c.decode(String.self, forKey: .reason))\n        }\n    }\n\n    public func encode(to encoder: any Encoder) throws {\n        var c = encoder.container(keyedBy: CodingKeys.self)\n        try c.encode(kind, forKey: .kind)\n        switch self {\n        case .bless: break\n        case .amend(let content): try c.encode(content, forKey: .content)\n        case .withhold(let reason): try c.encode(reason, forKey: .reason)\n        }\n    }\n}\n"},{"path":"Sources/Bless/Petition/Verdict.swift","status":"added","lang":"swift","hunks":[[1,0,1,51]],"header":{"lines":[1,14],"target":"Bless","what":[8,11],"pin":[12,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":152,"scopes":[["S","Verdict",null,"public",18,18,[18,52],51,null,-1,0,"a"],["i","init",["petitionID","reviewer","ruling","digest","note","issued","signature"],"public",29,29,[30,63],38,null,0,0,"a"],["v","endorsed",null,"public",41,41,[41,33],47,[40,40],0,0,"a"],["v","canonicalBytes",null,"public",50,50,[50,36],50,[49,49],0,8,"a"]],"old":"","new":"//\n//  Verdict.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: One reviewer's ruling on one petition, pinned to the exact text they read (`digest`)\n//        and, when sealed, signed with their key over its canonical bytes. `endorsed` is the\n//        text the verdict puts its name to: the digest itself for a blessing, the amendment's\n//        digest for an amendment, nothing for a withholding.\n//  PIN:  `issued` is stamped to whole milliseconds on creation, so the signed bytes survive a\n//        JSON round trip.\n//\n\nimport Foundation\n\npublic struct Verdict: Codable, Sendable, Equatable {\n    public let petitionID: Petition.ID\n    public let reviewer: Party.ID\n    public let ruling: Ruling\n    /// The SHA-256 of the text the reviewer read.\n    public let digest: Sha256\n    public let note: String?\n    public let issued: Date\n    /// The Ed25519 signature over `canonicalBytes`, when sealed.\n    public internal(set) var signature: Data?\n\n    public init(petitionID: Petition.ID, reviewer: Party.ID, ruling: Ruling, digest: Sha256, note: String? = nil,\n                issued: Date = Date(), signature: Data? = nil) {\n        self.petitionID = petitionID\n        self.reviewer = reviewer\n        self.ruling = ruling\n        self.digest = digest\n        self.note = note\n        self.issued = Canonical.stamp(issued)\n        self.signature = signature\n    }\n\n    /// The digest of the text this verdict endorses, or nil for a withholding.\n    public var endorsed: Sha256? {\n        switch ruling {\n        case .bless: digest\n        case .amend(let content): .of(content)\n        case .withhold: nil\n        }\n    }\n\n    /// The bytes a seal signs: everything but the signature (Canonical, `bless/verdict/1`).\n    public var canonicalBytes: Data { Canonical.verdict(self) }\n}\n"},{"path":"Sources/Bless/Seal/Seal.swift","status":"added","lang":"swift","hunks":[[1,0,1,39]],"header":{"lines":[1,14],"target":"Bless","what":[8,10],"pin":[11,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":156,"scopes":[["E","Seal",null,"public",19,19,[19,17],39,null,-1,0,"a",[]],["f","sign",["_","privateKey"],"public static",21,21,[21,88],31,[20,20],0,0,"a"],["f","verify",["_","verifyingKey"],"public static",34,34,[34,82],38,[33,33],0,0,"a"]],"old":"","new":"//\n//  Seal.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Signs a verdict with a reviewer's Ed25519 key and verifies one against the public key.\n//        What is signed is the verdict's canonical bytes (`bless/verdict/1`): the petition, the\n//        reviewer, the ruling and its text, the digest the reviewer read, the note, the time.\n//  PIN:  Curve25519.Signing (Ed25519, RFC 8032) from CryptoKit; any RFC 8032 verifier accepts\n//        these signatures (the site's figure verifies them with Web Crypto, INTEGRATION.md with\n//        Python's `cryptography`).\n//\n\nimport CryptoKit\nimport Foundation\n\npublic enum Seal {\n    /// The verdict with its signature.\n    public static func sign(_ verdict: Verdict, privateKey raw: Data) throws -> Verdict {\n        let key: Curve25519.Signing.PrivateKey\n        do {\n            key = try Curve25519.Signing.PrivateKey(rawRepresentation: raw)\n        } catch {\n            throw BlessError.invalidPolicy(\"a reviewer's private key is 32 raw bytes\")\n        }\n        var signed = verdict\n        signed.signature = try key.signature(for: verdict.canonicalBytes)\n        return signed\n    }\n\n    /// Whether the verdict carries a signature that this public key made over its bytes.\n    public static func verify(_ verdict: Verdict, verifyingKey raw: Data) -> Bool {\n        guard let signature = verdict.signature,\n              let key = try? Curve25519.Signing.PublicKey(rawRepresentation: raw) else { return false }\n        return key.isValidSignature(signature, for: verdict.canonicalBytes)\n    }\n}\n"},{"path":"Sources/Bless/Store/FilePetitionStore.swift","status":"added","lang":"swift","hunks":[[1,0,1,71]],"header":{"lines":[1,13],"target":"Bless","what":[8,10],"pin":[11,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":159,"scopes":[["C","FilePetitionStore",null,"public final",18,18,[18,52],71,null,-1,0,"a"],["i","init",["directory","cipher"],"public",23,23,[23,73],27,null,0,0,"a"],["v","suffix",null,"private",29,29,[29,31],29,null,0,8,"a"],["f","url",["_"],"private",31,31,[31,54],37,null,0,0,"a"],["f","save",["_"],"public",39,39,[39,50],44,null,0,0,"a"],["f","load",["_"],"public",46,46,[46,60],52,null,0,0,"a"],["f","all",[],"public",54,54,[54,43],61,null,0,0,"a"],["f","decode",["_"],"private",63,63,[63,57],70,null,0,0,"a"]],"old":"","new":"//\n//  FilePetitionStore.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Petitions kept as one private file each in a private directory: `<id>.json`, or\n//        `<id>.sealed` when a StoreCipher encrypts them. Writes are atomic, so a crash leaves\n//        either the old state or the new, never half of one.\n//  PIN:  Ids must be letters, digits and hyphens (what Petition.ID makes), so no id can name a\n//        path outside the directory.\n//\n\nimport Foundation\nimport Synchronization\n\npublic final class FilePetitionStore: PetitionStore {\n    public let directory: URL\n    private let cipher: (any StoreCipher)?\n    private let lock = Mutex<Void>(())\n\n    public init(directory: URL, cipher: (any StoreCipher)? = nil) throws {\n        self.directory = directory\n        self.cipher = cipher\n        try PrivateFile.createDirectory(directory)\n    }\n\n    private var suffix: String { cipher == nil ? \"json\" : \"sealed\" }\n\n    private func url(_ id: Petition.ID) throws -> URL {\n        let safe = !id.rawValue.isEmpty && id.rawValue.unicodeScalars.allSatisfy {\n            (\"a\"...\"z\").contains($0) || (\"A\"...\"Z\").contains($0) || (\"0\"...\"9\").contains($0) || $0 == \"-\"\n        }\n        guard safe else { throw BlessError.store(\"a petition id may hold only letters, digits and hyphens\") }\n        return directory.appendingPathComponent(\"\\(id.rawValue).\\(suffix)\")\n    }\n\n    public func save(_ petition: Petition) throws {\n        var data = try JSONCoding.encoder().encode(petition)\n        if let cipher { data = try cipher.seal(data) }\n        let target = try url(petition.id)\n        try lock.withLock { _ in try PrivateFile.writeAtomically(data, to: target) }\n    }\n\n    public func load(_ id: Petition.ID) throws -> Petition? {\n        let source = try url(id)\n        return try lock.withLock { _ in\n            guard FileManager.default.fileExists(atPath: source.path) else { return nil }\n            return try decode(try PrivateFile.read(source))\n        }\n    }\n\n    public func all() throws -> [Petition] {\n        try lock.withLock { _ in\n            let names = (try? FileManager.default.contentsOfDirectory(atPath: directory.path)) ?? []\n            return try names.filter { $0.hasSuffix(\".\\(suffix)\") && !$0.hasPrefix(\".\") }.map {\n                try decode(try PrivateFile.read(directory.appendingPathComponent($0)))\n            }\n        }.sorted(by: Petition.oldestFirst)\n    }\n\n    private func decode(_ data: Data) throws -> Petition {\n        let plain = try cipher?.open(data) ?? data\n        do {\n            return try JSONCoding.decoder().decode(Petition.self, from: plain)\n        } catch {\n            throw BlessError.store(\"a petition file did not decode\")\n        }\n    }\n}\n"},{"path":"Sources/Bless/Store/PetitionStore.swift","status":"added","lang":"swift","hunks":[[1,0,1,46]],"header":{"lines":[1,12],"target":"Bless","what":[8,10],"pin":[11,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":167,"scopes":[["P","PetitionStore",null,"public",17,17,[17,40],22,null,-1,0,"a"],["f","save",["_"],"",18,18,null,18,null,0,1,"a"],["f","load",["_"],"",19,19,null,19,null,0,1,"a"],["f","all",[],"",21,21,null,21,[20,20],0,1,"a"],["C","MemoryPetitionStore",null,"public final",24,24,[24,54],40,null,-1,0,"a"],["i","init",[],"public",27,27,[27,18],27,null,4,8,"a"],["f","save",["_"],"public",29,29,[29,50],31,null,4,0,"a"],["f","load",["_"],"public",33,33,[33,60],35,null,4,0,"a"],["f","all",[],"public",37,37,[37,43],39,null,4,0,"a"],["X","Petition",null,"",42,42,[42,19],46,null,-1,0,"a"],["f","oldestFirst",["_","_"],"static",43,43,[43,66],45,null,9,0,"a"]],"old":"","new":"//\n//  PetitionStore.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Where petitions are kept between their submission and their release: save one (a new\n//        petition or its latest state), load one, list them. In memory here; FilePetitionStore\n//        keeps one private file per petition, optionally sealed with AES-GCM.\n//  PIN:  Synchronous on purpose, as LedgerStore: the Gate's transitions must not suspend.\n//\n\nimport Foundation\nimport Synchronization\n\npublic protocol PetitionStore: Sendable {\n    func save(_ petition: Petition) throws\n    func load(_ id: Petition.ID) throws -> Petition?\n    /// Every petition, oldest first.\n    func all() throws -> [Petition]\n}\n\npublic final class MemoryPetitionStore: PetitionStore {\n    private let petitions = Mutex<[Petition.ID: Petition]>([:])\n\n    public init() {}\n\n    public func save(_ petition: Petition) throws {\n        petitions.withLock { $0[petition.id] = petition }\n    }\n\n    public func load(_ id: Petition.ID) throws -> Petition? {\n        petitions.withLock { $0[id] }\n    }\n\n    public func all() throws -> [Petition] {\n        petitions.withLock { Array($0.values) }.sorted(by: Petition.oldestFirst)\n    }\n}\n\nextension Petition {\n    static func oldestFirst(_ a: Petition, _ b: Petition) -> Bool {\n        a.submitted == b.submitted ? a.id.rawValue < b.id.rawValue : a.submitted < b.submitted\n    }\n}\n"},{"path":"Sources/Bless/Store/PrivateFile.swift","status":"added","lang":"swift","hunks":[[1,0,1,85]],"header":{"lines":[1,11],"target":"Bless","what":[8,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":178,"scopes":[["E","PrivateFile",null,"",15,15,[15,17],85,null,-1,0,"a",[]],["f","createDirectory",["_"],"static",16,16,[16,51],23,null,0,0,"a"],["f","touch",["_"],"static",26,26,[26,41],30,[25,25],0,0,"a"],["f","writeAtomically",["_","to"],"static",32,32,[32,66],50,null,0,0,"a"],["f","append",["_","to"],"static",52,52,[52,57],58,null,0,0,"a"],["f","read",["_"],"static",60,60,[60,48],66,null,0,0,"a"],["f","writeAll",["_","to","url"],"private static",68,68,[68,78],80,null,0,0,"a"],["f","failure",["_","_"],"private static",82,82,[82,74],84,null,0,0,"a"]],"old":"","new":"//\n//  PrivateFile.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Files only their owner can read: directories made 0700, files 0600, whole-file writes\n//        that land atomically (a temporary file beside the target, flushed, then renamed over\n//        it), and appends flushed to disk before they return.\n//\n\nimport Foundation\n\nenum PrivateFile {\n    static func createDirectory(_ url: URL) throws {\n        do {\n            try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true,\n                                                    attributes: [.posixPermissions: 0o700])\n        } catch {\n            throw BlessError.store(\"cannot create \\(url.lastPathComponent): \\(error.localizedDescription)\")\n        }\n    }\n\n    /// Creates an empty 0600 file if none is there.\n    static func touch(_ url: URL) throws {\n        let fd = open(url.path, O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0o600)\n        guard fd >= 0 else { throw failure(\"open\", url) }\n        close(fd)\n    }\n\n    static func writeAtomically(_ data: Data, to url: URL) throws {\n        let temporary = url.deletingLastPathComponent()\n            .appendingPathComponent(\".\\(url.lastPathComponent).\\(UUID().uuidString.lowercased()).tmp\")\n        let fd = open(temporary.path, O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC, 0o600)\n        guard fd >= 0 else { throw failure(\"open\", temporary) }\n        do {\n            try writeAll(data, to: fd, url: temporary)\n            guard fsync(fd) == 0 else { throw failure(\"flush\", temporary) }\n            close(fd)\n        } catch {\n            close(fd)\n            unlink(temporary.path)\n            throw error\n        }\n        guard rename(temporary.path, url.path) == 0 else {\n            unlink(temporary.path)\n            throw failure(\"rename\", url)\n        }\n    }\n\n    static func append(_ data: Data, to url: URL) throws {\n        let fd = open(url.path, O_WRONLY | O_CREAT | O_APPEND | O_CLOEXEC, 0o600)\n        guard fd >= 0 else { throw failure(\"open\", url) }\n        defer { close(fd) }\n        try writeAll(data, to: fd, url: url)\n        guard fsync(fd) == 0 else { throw failure(\"flush\", url) }\n    }\n\n    static func read(_ url: URL) throws -> Data {\n        do {\n            return try Data(contentsOf: url)\n        } catch {\n            throw BlessError.store(\"cannot read \\(url.lastPathComponent): \\(error.localizedDescription)\")\n        }\n    }\n\n    private static func writeAll(_ data: Data, to fd: Int32, url: URL) throws {\n        try data.withUnsafeBytes { (buffer: UnsafeRawBufferPointer) in\n            var offset = 0\n            while offset < buffer.count {\n                let written = write(fd, buffer.baseAddress! + offset, buffer.count - offset)\n                if written < 0 {\n                    if errno == EINTR { continue }\n                    throw failure(\"write\", url)\n                }\n                offset += written\n            }\n        }\n    }\n\n    private static func failure(_ verb: String, _ url: URL) -> BlessError {\n        .store(\"cannot \\(verb) \\(url.lastPathComponent): \\(String(cString: strerror(errno)))\")\n    }\n}\n"},{"path":"Sources/Bless/Store/StoreCipher.swift","status":"added","lang":"swift","hunks":[[1,0,1,56]],"header":{"lines":[1,13],"target":"Bless","what":[8,10],"pin":[11,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":186,"scopes":[["P","StoreCipher",null,"public",18,18,[18,38],21,null,-1,0,"a"],["f","seal",["_"],"",19,19,null,19,null,0,1,"a"],["f","open",["_"],"",20,20,null,20,null,0,1,"a"],["S","AESGCMCipher",null,"public",23,23,[23,40],56,null,-1,0,"a"],["i","init",["keyData"],"public",27,27,[27,38],30,[26,26],3,0,"a"],["i","init",["key"],"public",33,33,[33,42],35,[32,32],3,0,"a"],["f","generateKey",[],"public static",38,38,[38,45],40,[37,37],3,0,"a"],["f","seal",["_"],"public",42,42,[42,55],47,null,3,0,"a"],["f","open",["_"],"public",49,49,[49,56],55,null,3,0,"a"]],"old":"","new":"//\n//  StoreCipher.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Encryption at rest for a petition store: `seal` before a petition is written, `open`\n//        after it is read. AESGCMCipher is AES-256-GCM (CryptoKit), nonce and tag kept with the\n//        ciphertext; a wrong key or a changed byte fails to open.\n//  PIN:  Where the key comes from (Keychain, Secure Enclave, a KMS) and how it rotates are the\n//        host's, and still open. The key is held as its raw bytes.\n//\n\nimport CryptoKit\nimport Foundation\n\npublic protocol StoreCipher: Sendable {\n    func seal(_ plaintext: Data) throws -> Data\n    func open(_ ciphertext: Data) throws -> Data\n}\n\npublic struct AESGCMCipher: StoreCipher {\n    private let key: Data\n\n    /// A cipher over a 32-byte key.\n    public init(keyData: Data) throws {\n        guard keyData.count == 32 else { throw BlessError.store(\"an AES-256 key is 32 bytes\") }\n        self.key = keyData\n    }\n\n    /// A cipher over a CryptoKit key.\n    public init(key: SymmetricKey) throws {\n        try self.init(keyData: key.withUnsafeBytes { Data($0) })\n    }\n\n    /// Thirty-two fresh random bytes, for a new key.\n    public static func generateKey() -> Data {\n        SymmetricKey(size: .bits256).withUnsafeBytes { Data($0) }\n    }\n\n    public func seal(_ plaintext: Data) throws -> Data {\n        guard let combined = try AES.GCM.seal(plaintext, using: SymmetricKey(data: key)).combined else {\n            throw BlessError.store(\"AES-GCM produced no output\")\n        }\n        return combined\n    }\n\n    public func open(_ ciphertext: Data) throws -> Data {\n        do {\n            return try AES.GCM.open(try AES.GCM.SealedBox(combined: ciphertext), using: SymmetricKey(data: key))\n        } catch {\n            throw BlessError.store(\"a sealed petition did not open: the wrong key, or a changed file\")\n        }\n    }\n}\n"},{"path":"Sources/Bless/Support/BlessError.swift","status":"added","lang":"swift","hunks":[[1,0,1,95]],"header":{"lines":[1,11],"target":"Bless","what":[8,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":195,"scopes":[["E","BlessError",null,"public",15,15,[15,66],95,null,-1,0,"a",["unknownPetition","invalidDraft","invalidPolicy","notAReviewer","alreadyDecided","staleVerdict","duplicateVerdict","amendmentNotAllowed","sealRequired","badSeal","withheld","expired","withdrawn","notBlessed","invalidRelease","ledgerTampered","store"]],["v","code",null,"public",52,52,[52,28],72,[51,51],0,0,"a"],["v","description",null,"public",74,74,[74,35],94,null,0,0,"a"]],"old":"","new":"//\n//  BlessError.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Every way a Bless call can refuse. `code` is the case's name: the only part of an error\n//        the ledger ever records, so an error's details (a reason, a store path) stay out of the\n//        audit log.\n//\n\nimport Foundation\n\npublic enum BlessError: Error, Equatable, CustomStringConvertible {\n    /// No petition with this id is in the store.\n    case unknownPetition(Petition.ID)\n    /// The draft cannot be held: not the assistant's, or empty.\n    case invalidDraft(String)\n    /// The policy cannot be met by these reviewers.\n    case invalidPolicy(String)\n    /// The party is not one of the petition's reviewers.\n    case notAReviewer(Party.ID)\n    /// The petition has already been decided (or withdrawn); nothing more is accepted.\n    case alreadyDecided(Petition.ID, Petition.Standing)\n    /// The verdict was given on a text that is no longer the petition's.\n    case staleVerdict(expected: Sha256, saw: Sha256)\n    /// This reviewer has already blessed this text.\n    case duplicateVerdict(Party.ID)\n    /// The policy does not let reviewers change the text.\n    case amendmentNotAllowed\n    /// The policy needs a sealed verdict and this one is not, or the reviewer has no key.\n    case sealRequired(Party.ID)\n    /// The verdict's seal does not verify against the reviewer's key.\n    case badSeal(Party.ID)\n    /// A reviewer withheld the reply. The reason is the reviewer's, for the host's own records.\n    case withheld(Petition.ID, reason: String)\n    /// The deadline passed and the policy withholds a lapsed reply.\n    case expired(Petition.ID)\n    /// The petition was withdrawn before it was decided.\n    case withdrawn(Petition.ID)\n    /// There is nothing to release yet: the petition is not blessed.\n    case notBlessed(Petition.ID)\n    /// A release does not match its petition.\n    case invalidRelease(String)\n    /// The ledger's chain breaks at this event.\n    case ledgerTampered(seq: Int)\n    /// A store could not read or write.\n    case store(String)\n\n    /// The case's name, and nothing else: what the ledger may record.\n    public var code: String {\n        switch self {\n        case .unknownPetition: \"unknownPetition\"\n        case .invalidDraft: \"invalidDraft\"\n        case .invalidPolicy: \"invalidPolicy\"\n        case .notAReviewer: \"notAReviewer\"\n        case .alreadyDecided: \"alreadyDecided\"\n        case .staleVerdict: \"staleVerdict\"\n        case .duplicateVerdict: \"duplicateVerdict\"\n        case .amendmentNotAllowed: \"amendmentNotAllowed\"\n        case .sealRequired: \"sealRequired\"\n        case .badSeal: \"badSeal\"\n        case .withheld: \"withheld\"\n        case .expired: \"expired\"\n        case .withdrawn: \"withdrawn\"\n        case .notBlessed: \"notBlessed\"\n        case .invalidRelease: \"invalidRelease\"\n        case .ledgerTampered: \"ledgerTampered\"\n        case .store: \"store\"\n        }\n    }\n\n    public var description: String {\n        switch self {\n        case .unknownPetition(let id): \"no petition \\(id)\"\n        case .invalidDraft(let why): \"the draft cannot be held: \\(why)\"\n        case .invalidPolicy(let why): \"the policy cannot be met: \\(why)\"\n        case .notAReviewer(let id): \"\\(id) is not a reviewer of this petition\"\n        case .alreadyDecided(let id, let standing): \"petition \\(id) is already \\(standing.rawValue)\"\n        case .staleVerdict(let expected, let saw): \"the verdict was given on \\(saw.prefix), but the petition's text is now \\(expected.prefix)\"\n        case .duplicateVerdict(let id): \"\\(id) has already blessed this text\"\n        case .amendmentNotAllowed: \"the policy does not allow amendments\"\n        case .sealRequired(let id): \"the policy requires a sealed verdict from \\(id)\"\n        case .badSeal(let id): \"the seal on \\(id)'s verdict does not verify\"\n        case .withheld(let id, _): \"petition \\(id) was withheld by its reviewer\"\n        case .expired(let id): \"petition \\(id) lapsed at its deadline and was withheld\"\n        case .withdrawn(let id): \"petition \\(id) was withdrawn\"\n        case .notBlessed(let id): \"petition \\(id) has nothing to release\"\n        case .invalidRelease(let why): \"the release does not match its petition: \\(why)\"\n        case .ledgerTampered(let seq): \"the ledger's chain breaks at event \\(seq)\"\n        case .store(let why): \"store: \\(why)\"\n        }\n    }\n}\n"},{"path":"Sources/Bless/Support/Canonical.swift","status":"added","lang":"swift","hunks":[[1,0,1,120]],"header":{"lines":[1,23],"target":"Bless","what":[8,17],"pin":[18,22],"in":null,"out":null,"style":"swift"},"marks":[],"first":198,"scopes":[["E","Canonical",null,"",27,27,[27,15],120,null,-1,0,"a",[]],["S","Writer",null,"",29,29,[29,18],65,[28,28],0,0,"a"],["f","tag",["_"],"mutating",32,32,[32,41],34,null,1,0,"a"],["f","string",["_"],"mutating",36,36,[36,46],40,null,1,0,"a"],["f","optional",["_"],"mutating",42,42,[42,49],46,null,1,0,"a"],["f","int64",["_"],"mutating",48,48,[48,44],50,null,1,0,"a"],["f","sha256",["_"],"mutating",52,52,[52,46],54,null,1,0,"a"],["f","optional",["_"],"mutating",56,56,[56,49],60,null,1,0,"a"],["f","uint32",["_"],"private mutating",62,62,[62,54],64,null,1,0,"a"],["f","milliseconds",["_"],"static",72,72,[72,52],74,[70,71],0,0,"a"],["f","date",["milliseconds"],"static",77,77,[77,50],79,[76,76],0,0,"a"],["f","stamp",["_"],"static",82,82,[82,44],84,[81,81],0,0,"a"],["f","verdict",["_"],"static",87,87,[87,52],102,[86,86],0,0,"a"],["f","event",["seq","at","kind","petitionID","actor","digest","code","previous"],"static",106,106,[107,98],119,[104,105],0,0,"a"]],"old":"","new":"//\n//  Canonical.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The exact bytes a seal signs and a ledger hash covers. Each record starts with a\n//        domain tag that names its layout and version (`bless/verdict/1`, `bless/event/1`), then\n//        its fields in a fixed order, each written one way:\n//          string    UInt32 big-endian byte count, then the UTF-8 bytes as given\n//          int64     8 bytes big-endian (timestamps are whole milliseconds since 1970)\n//          sha256    the 32 raw bytes\n//          optional  0x00 for absent, or 0x01 then the value\n//        Enum cases are written as their raw-value strings, so reordering a Swift enum never\n//        changes a signature. Docs/INTEGRATION.md shows the layout field by field, and the site\n//        recomputes it in the browser (js/hash.js).\n//  PIN:  Not JSON. JSONEncoder's bytes for numbers, dates and escapes have changed across\n//        Foundation rewrites, and a signature must outlive them. Changing a layout means a new\n//        domain tag (`/2`), never an edit to `/1`: every stored signature depends on it.\n//        Every Bless timestamp passes through `stamp` first, so a JSON round trip (which keeps\n//        milliseconds) gives back the exact Date that was signed.\n//\n\nimport Foundation\n\nenum Canonical {\n    /// Appends fields in the canonical forms.\n    struct Writer {\n        private(set) var data = Data()\n\n        mutating func tag(_ tag: String) {\n            string(tag)\n        }\n\n        mutating func string(_ value: String) {\n            let utf8 = Data(value.utf8)\n            uint32(UInt32(utf8.count))\n            data.append(utf8)\n        }\n\n        mutating func optional(_ value: String?) {\n            guard let value else { return data.append(0) }\n            data.append(1)\n            string(value)\n        }\n\n        mutating func int64(_ value: Int64) {\n            withUnsafeBytes(of: value.bigEndian) { data.append(contentsOf: $0) }\n        }\n\n        mutating func sha256(_ value: Sha256) {\n            data.append(value.bytes)\n        }\n\n        mutating func optional(_ value: Sha256?) {\n            guard let value else { return data.append(0) }\n            data.append(1)\n            sha256(value)\n        }\n\n        private mutating func uint32(_ value: UInt32) {\n            withUnsafeBytes(of: value.bigEndian) { data.append(contentsOf: $0) }\n        }\n    }\n\n    static let verdictTag = \"bless/verdict/1\"\n    static let eventTag = \"bless/event/1\"\n\n    /// Whole milliseconds since 1970. Rounds, so a stamped Date read back from JSON gives back\n    /// the same count.\n    static func milliseconds(_ date: Date) -> Int64 {\n        Int64((date.timeIntervalSince1970 * 1000).rounded())\n    }\n\n    /// A date from whole milliseconds since 1970.\n    static func date(milliseconds: Int64) -> Date {\n        Date(timeIntervalSince1970: Double(milliseconds) / 1000)\n    }\n\n    /// The date truncated to whole milliseconds: what Bless stores, signs and chains.\n    static func stamp(_ date: Date) -> Date {\n        Self.date(milliseconds: Int64((date.timeIntervalSince1970 * 1000).rounded(.down)))\n    }\n\n    /// What a reviewer's seal signs: everything in the verdict but the signature.\n    static func verdict(_ verdict: Verdict) -> Data {\n        var writer = Writer()\n        writer.tag(verdictTag)\n        writer.string(verdict.petitionID.rawValue)\n        writer.string(verdict.reviewer.rawValue)\n        writer.string(verdict.ruling.kind.rawValue)\n        switch verdict.ruling {\n        case .bless: break\n        case .amend(let content): writer.string(content)\n        case .withhold(let reason): writer.string(reason)\n        }\n        writer.sha256(verdict.digest)\n        writer.optional(verdict.note)\n        writer.int64(milliseconds(verdict.issued))\n        return writer.data\n    }\n\n    /// What a ledger event's hash covers: everything in the event but the hash itself,\n    /// `previous` last, so each hash commits to the whole chain before it.\n    static func event(seq: Int, at: Date, kind: LedgerEvent.Kind, petitionID: Petition.ID,\n                      actor: Party.ID?, digest: Sha256?, code: String?, previous: Sha256) -> Data {\n        var writer = Writer()\n        writer.tag(eventTag)\n        writer.int64(Int64(seq))\n        writer.int64(milliseconds(at))\n        writer.string(kind.rawValue)\n        writer.string(petitionID.rawValue)\n        writer.optional(actor?.rawValue)\n        writer.optional(digest)\n        writer.optional(code)\n        writer.sha256(previous)\n        return writer.data\n    }\n}\n"},{"path":"Sources/Bless/Support/JSONCoding.swift","status":"added","lang":"swift","hunks":[[1,0,1,44]],"header":{"lines":[1,12],"target":"Bless","what":[8,9],"pin":[10,11],"in":null,"out":null,"style":"swift"},"marks":[],"first":212,"scopes":[["E","JSONCoding",null,"public",16,16,[16,23],44,null,-1,0,"a",[]],["f","encoder",[],"public static",18,18,[18,48],26,[17,17],0,0,"a"],["f","prettyEncoder",[],"public static",29,29,[29,54],33,[28,28],0,0,"a"],["f","decoder",[],"public static",36,36,[36,48],43,[35,35],0,0,"a"]],"old":"","new":"//\n//  JSONCoding.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: The JSON every Bless store and export writes: keys sorted, dates as whole milliseconds\n//        since 1970 (integers), data as base64. Read it back with `decoder()`.\n//  PIN:  Integer milliseconds, not ISO 8601: Foundation's ISO 8601 drops fractional seconds,\n//        and a verdict whose `issued` moved by a millisecond would no longer verify.\n//\n\nimport Foundation\n\npublic enum JSONCoding {\n    /// Sorted keys, integer-millisecond dates, compact.\n    public static func encoder() -> JSONEncoder {\n        let encoder = JSONEncoder()\n        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes]\n        encoder.dateEncodingStrategy = .custom { date, encoder in\n            var container = encoder.singleValueContainer()\n            try container.encode(Canonical.milliseconds(date))\n        }\n        return encoder\n    }\n\n    /// The same, indented, for files a person reads.\n    public static func prettyEncoder() -> JSONEncoder {\n        let encoder = encoder()\n        encoder.outputFormatting = [.sortedKeys, .withoutEscapingSlashes, .prettyPrinted]\n        return encoder\n    }\n\n    /// Reads what `encoder()` writes.\n    public static func decoder() -> JSONDecoder {\n        let decoder = JSONDecoder()\n        decoder.dateDecodingStrategy = .custom { decoder in\n            let container = try decoder.singleValueContainer()\n            return Canonical.date(milliseconds: try container.decode(Int64.self))\n        }\n        return decoder\n    }\n}\n"},{"path":"Sources/Bless/Support/JSONValue.swift","status":"added","lang":"swift","hunks":[[1,0,1,67]],"header":{"lines":[1,10],"target":"Bless","what":[8,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":216,"scopes":[["E","JSONValue",null,"public",14,14,[14,51],55,null,-1,0,"a",["string","number","bool","null","array","object"]],["i","init",["from"],"public",22,22,[22,50],37,null,0,0,"a"],["f","encode",["to"],"public",39,39,[39,55],54,null,0,0,"a"],["X","JSONValue",null,"",57,57,[58,89],67,null,-1,0,"a"],["i","init",["stringLiteral"],"public",59,59,[59,45],59,null,3,8,"a"],["i","init",["integerLiteral"],"public",60,60,[60,43],60,null,3,8,"a"],["i","init",["floatLiteral"],"public",61,61,[61,44],61,null,3,8,"a"],["i","init",["booleanLiteral"],"public",62,62,[62,44],62,null,3,8,"a"],["i","init",["arrayLiteral"],"public",63,63,[63,53],63,null,3,8,"a"],["i","init",["dictionaryLiteral"],"public",64,64,[64,68],66,null,3,0,"a"]],"old":"","new":"//\n//  JSONValue.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: Any JSON value, for the provider-specific fields a chat request carries beside the\n//        standard ones (Sewn's required `sewn` object, a vendor's `safe_prompt`).\n//\n\nimport Foundation\n\npublic enum JSONValue: Codable, Sendable, Hashable {\n    case string(String)\n    case number(Double)\n    case bool(Bool)\n    case null\n    case array([JSONValue])\n    case object([String: JSONValue])\n\n    public init(from decoder: any Decoder) throws {\n        let container = try decoder.singleValueContainer()\n        if container.decodeNil() {\n            self = .null\n        } else if let value = try? container.decode(Bool.self) {\n            self = .bool(value)\n        } else if let value = try? container.decode(Double.self) {\n            self = .number(value)\n        } else if let value = try? container.decode(String.self) {\n            self = .string(value)\n        } else if let value = try? container.decode([JSONValue].self) {\n            self = .array(value)\n        } else {\n            self = .object(try container.decode([String: JSONValue].self))\n        }\n    }\n\n    public func encode(to encoder: any Encoder) throws {\n        var container = encoder.singleValueContainer()\n        switch self {\n        case .string(let value): try container.encode(value)\n        case .number(let value):\n            if value.rounded() == value, abs(value) < 9.0e15 {\n                try container.encode(Int64(value))\n            } else {\n                try container.encode(value)\n            }\n        case .bool(let value): try container.encode(value)\n        case .null: try container.encodeNil()\n        case .array(let value): try container.encode(value)\n        case .object(let value): try container.encode(value)\n        }\n    }\n}\n\nextension JSONValue: ExpressibleByStringLiteral, ExpressibleByIntegerLiteral, ExpressibleByBooleanLiteral,\n    ExpressibleByArrayLiteral, ExpressibleByDictionaryLiteral, ExpressibleByFloatLiteral {\n    public init(stringLiteral value: String) { self = .string(value) }\n    public init(integerLiteral value: Int) { self = .number(Double(value)) }\n    public init(floatLiteral value: Double) { self = .number(value) }\n    public init(booleanLiteral value: Bool) { self = .bool(value) }\n    public init(arrayLiteral elements: JSONValue...) { self = .array(elements) }\n    public init(dictionaryLiteral elements: (String, JSONValue)...) {\n        self = .object(Dictionary(elements, uniquingKeysWith: { _, last in last }))\n    }\n}\n"},{"path":"Sources/Bless/Support/Sha256.swift","status":"added","lang":"swift","hunks":[[1,0,1,85]],"header":{"lines":[1,14],"target":"Bless","what":[8,11],"pin":[12,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":226,"scopes":[["S","Sha256",null,"public",19,19,[19,75],85,null,-1,0,"a"],["i","init",["unchecked"],"",23,23,[23,32],25,null,0,0,"a"],["i","init",["bytes"],"public",28,28,[28,30],31,[27,27],0,0,"a"],["i","init",["hex"],"public",34,34,[34,30],45,[33,33],0,0,"a"],["f","of",["_"],"public static",48,48,[48,52],50,[47,47],0,0,"a"],["f","of",["_"],"public static",53,53,[53,50],55,[52,52],0,0,"a"],["v","hex",null,"public",61,61,[61,27],63,[60,60],0,0,"a"],["v","prefix",null,"public",66,66,[66,30],68,[65,65],0,0,"a"],["v","description",null,"public",70,70,[70,35],70,null,0,8,"a"],["i","init",["from"],"public",72,72,[72,50],79,null,0,0,"a"],["f","encode",["to"],"public",81,81,[81,55],84,null,0,0,"a"]],"old":"","new":"//\n//  Sha256.swift\n//  Bless\n//\n//  Created by Ritesh Pakala on 10/20/26.\n//  Copyright © 2026 Rao Studios LLC.\n//\n//  WHAT: A SHA-256 digest as a value: what a petition's text is pinned to, what a verdict\n//        endorses, and what links one ledger event to the next. `Sha256.of(\"text\")` is the\n//        digest of the string's UTF-8 bytes exactly as given (no normalization), so\n//        `printf %s text | shasum -a 256` reproduces it. JSON carries it as lowercase hex.\n//  PIN:  Named Sha256, not Digest: CryptoKit and swift-crypto both declare a `Digest` protocol,\n//        and a Sewn file importing both would otherwise have to qualify every use.\n//\n\nimport CryptoKit\nimport Foundation\n\npublic struct Sha256: Hashable, Sendable, Codable, CustomStringConvertible {\n    /// The 32 bytes of the digest.\n    public let bytes: Data\n\n    init(unchecked bytes: Data) {\n        self.bytes = bytes\n    }\n\n    /// A digest from its 32 raw bytes, or nil for any other length.\n    public init?(bytes: Data) {\n        guard bytes.count == 32 else { return nil }\n        self.bytes = bytes\n    }\n\n    /// A digest from 64 hex digits (either case), or nil.\n    public init?(hex: String) {\n        guard hex.utf8.count == 64 else { return nil }\n        var out = Data(capacity: 32)\n        var index = hex.startIndex\n        while index < hex.endIndex {\n            let next = hex.index(index, offsetBy: 2)\n            guard let byte = UInt8(hex[index..<next], radix: 16) else { return nil }\n            out.append(byte)\n            index = next\n        }\n        self.bytes = out\n    }\n\n    /// The digest of a string's UTF-8 bytes, exactly as given.\n    public static func of(_ text: String) -> Sha256 {\n        of(Data(text.utf8))\n    }\n\n    /// The digest of some bytes.\n    public static func of(_ data: Data) -> Sha256 {\n        Sha256(unchecked: Data(SHA256.hash(data: data)))\n    }\n\n    /// Thirty-two zero bytes: the `previous` of a ledger's first event.\n    public static let zero = Sha256(unchecked: Data(count: 32))\n\n    /// Lowercase hex, 64 digits.\n    public var hex: String {\n        bytes.map { String(format: \"%02x\", $0) }.joined()\n    }\n\n    /// The first twelve hex digits, for a person to compare at a glance.\n    public var prefix: String {\n        String(hex.prefix(12))\n    }\n\n    public var description: String { hex }\n\n    public init(from decoder: any Decoder) throws {\n        let container = try decoder.singleValueContainer()\n        let text = try container.decode(String.self)\n        guard let value = Sha256(hex: text) else {\n            throw DecodingError.dataCorruptedError(in: container, debugDescription: \"not a SHA-256 in hex: \\(text.prefix(80))\")\n        }\n        self = value\n    }\n\n    public func encode(to encoder: any Encoder) throws {\n        var container = encoder.singleValueContainer()\n        try container.encode(hex)\n    }\n}\n"}]};
